// Generated by generators/create-events-file.ts — do not edit by hand.
import type { EventMapping } from '../generators/create-events-file'
export const EVENTS: EventMapping = {"battle-of-marathon":{"name":"Battle of Marathon","country":"GR","kind":"conflict","year":-490,"description":"Athens beat back the first Persian invasion of Greece on the plain of Marathon. The modern 42-kilometre race is named for the messenger legend that grew out of it.","image":"/events/battle-of-marathon.webp","credit":"John Steeple Davis","license":"Public domain"},"battle-of-thermopylae":{"name":"Battle of Thermopylae","country":"GR","kind":"conflict","year":-480,"description":"King Leonidas and his rearguard — the famous three hundred Spartans among them — held the mountain pass at Thermopylae for days against the vast Persian army before being wiped out.","image":"/events/battle-of-thermopylae.webp","license":"Public domain"},"death-of-alexander-the-great":{"name":"Death of Alexander the Great","country":"IQ","kind":"politics","year":-323,"description":"Alexander died in Babylon at thirty-two, ruler of an empire reaching from Greece to India. His generals immediately carved it apart.","image":"/events/death-of-alexander-the-great.webp","credit":"Urek Meniashvili","license":"CC BY-SA 3.0"},"qin-s-wars-of-unification":{"name":"China is unified under its First Emperor","country":"CN","kind":"nation","year":-221,"description":"The state of Qin swallowed the last of its rival kingdoms and its king proclaimed himself Qin Shi Huang — First Emperor. Standard script, currency and measures followed; so did the first Great Wall.","image":"/events/qin-s-wars-of-unification.webp","credit":"Benedetta blair","license":"CC BY-SA 4.0"},"assassination-of-julius-caesar":{"name":"Assassination of Julius Caesar","country":"IT","kind":"politics","year":-44,"description":"Rome's dictator was stabbed by dozens of senators at a Senate meeting on the Ides of March. The republic they claimed to save died with him — his heir became the first emperor.","image":"/events/assassination-of-julius-caesar.webp","credit":"Vincenzo Camuccini","license":"Public domain"},"battle-of-actium":{"name":"Battle of Actium","country":"GR","kind":"conflict","year":-31,"description":"Octavian's fleet crushed Antony and Cleopatra off the west coast of Greece. Egypt fell, both lovers died by suicide, and Octavian ruled Rome alone as Augustus.","image":"/events/battle-of-actium.webp","credit":"Laureys a Castro","license":"Public domain"},"eruption-of-mount-vesuvius-in-79-ad":{"name":"Vesuvius buries Pompeii","country":"IT","kind":"disaster","year":79,"description":"Vesuvius erupted and buried Pompeii and Herculaneum under metres of ash, freezing two Roman towns mid-breath. They stayed sealed for over 1,500 years.","image":"/events/eruption-of-mount-vesuvius-in-79-ad.webp","credit":"Ivan Aivazovsky","license":"Public domain"},"edict-of-milan":{"name":"Edict of Milan","country":"IT","kind":"politics","year":313,"description":"Constantine and his co-emperor agreed to tolerate Christianity across the Roman Empire, ending centuries of persecution. Within a century it was the state religion.","image":"/events/edict-of-milan.webp","credit":"Marie-Lan Nguyen","license":"Public domain"},"fall-of-the-western-roman-empire":{"name":"Fall of the Western Roman Empire","country":"IT","kind":"nation","year":476,"description":"The Germanic commander Odoacer deposed the teenage emperor Romulus Augustulus and did not bother appointing another. The eastern half of the empire carried on from Constantinople for another thousand years."},"hegira":{"name":"The Hegira — Muhammad leaves Mecca for Medina","country":"SA","kind":"culture","year":622,"description":"Muhammad and his followers left Mecca for Medina to escape persecution. The journey counts as year one of the Islamic calendar.","image":"/events/hegira.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"coronation-of-charlemagne":{"name":"Charlemagne is crowned emperor","country":"FR","kind":"politics","year":800,"description":"Pope Leo III crowned the Frankish king Charlemagne emperor in Rome on Christmas Day — the first western emperor in three centuries, and the seed of the Holy Roman Empire.","image":"/events/coronation-of-charlemagne.webp","credit":"Raphael","license":"Public domain"},"althing":{"name":"Iceland founds the Althing","country":"IS","kind":"culture","year":930,"description":"Icelandic chieftains began meeting each summer at Þingvellir in an assembly called the Althing. It still sits today — the world's oldest surviving parliament.","image":"/events/althing.webp","credit":"Bragi Thór Josefsson","license":"Public domain"},"christianization-of-kievan-rus":{"name":"Christianization of Kievan Rus'","country":"UA","kind":"culture","year":988,"description":"Grand Prince Vladimir of Kyiv had himself and his people baptised into Byzantine Christianity, mass-christening them in the Dnieper. Eastern Europe's religious map was drawn that day.","image":"/events/christianization-of-kievan-rus.webp","credit":"Klavdy Lebedev","license":"Public domain"},"east-west-schism":{"name":"The Great Schism splits Christianity","country":"VA","kind":"culture","year":1054,"description":"Rome and Constantinople excommunicated each other, splitting Christianity into Catholic and Orthodox halves. The mutual excommunications were only lifted in 1965.","image":"/events/east-west-schism.webp","license":"Public domain"},"battle-of-hastings":{"name":"Battle of Hastings","country":"GB","kind":"conflict","year":1066,"description":"William of Normandy killed King Harold and took England in a single October day. The conquest rewired the English language, law and aristocracy.","image":"/events/battle-of-hastings.webp","credit":"Myrabella","license":"Public domain"},"university-of-bologna":{"name":"The first university opens in Bologna","country":"IT","kind":"culture","year":1088,"description":"Law students in Bologna organised the institution now counted as the world's first university. The word universitas was coined for it.","image":"/events/university-of-bologna.webp","credit":"Utente:Mattia Barci","license":"CC BY-SA 4.0"},"siege-of-jerusalem-1099":{"name":"The First Crusade takes Jerusalem","country":"IL","kind":"conflict","year":1099,"description":"After a three-year march across Europe and Anatolia, the First Crusade stormed Jerusalem and massacred much of the city, founding a crusader kingdom that lasted not quite two centuries.","image":"/events/siege-of-jerusalem-1099.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"mongol-empire":{"name":"Genghis Khan founds the Mongol Empire","country":"MN","kind":"nation","year":1206,"description":"Temüjin united the feuding steppe tribes and took the title Genghis Khan. His descendants built the largest contiguous land empire in history.","image":"/events/mongol-empire.webp","credit":"DannamEmpire","license":"CC BY 4.0"},"magna-carta":{"name":"Magna Carta","country":"GB","kind":"politics","year":1215,"description":"Rebel barons cornered King John at Runnymede and made him seal a charter putting the king himself under the law. He repudiated it within weeks — but the idea never went away.","image":"/events/magna-carta.webp","license":"Public domain"},"ottoman-empire":{"name":"Osman founds the Ottoman state","country":"TR","kind":"nation","year":1299,"description":"A frontier warlord named Osman began carving a state out of crumbling Byzantine Anatolia. His house went on to rule an empire on three continents for six centuries.","image":"/events/ottoman-empire.webp","credit":"User6054","license":"CC0"},"black-death":{"name":"The Black Death reaches Europe","country":"IT","kind":"disaster","year":1347,"description":"Plague arrived in Sicily aboard Genoese ships and burned through the continent, killing perhaps a third to a half of Europe within five years.","image":"/events/black-death.webp","credit":"Pierart dou Tielt (fl. 1340-1360)","license":"Public domain"},"kalmar-union":{"name":"Scandinavia unites under one crown","country":"DK","kind":"politics","year":1397,"description":"Denmark, Sweden and Norway were joined under a single monarch at Kalmar, run for most of its life from Copenhagen. Sweden fought its way out in 1523."},"battle-of-grunwald":{"name":"Battle of Grunwald","country":"PL","kind":"conflict","year":1410,"description":"A combined Polish–Lithuanian army destroyed the Teutonic Knights in one of medieval Europe's largest battles, breaking the crusading order's power for good.","image":"/events/battle-of-grunwald.webp","credit":"Jan Matejko","license":"Public domain"},"ming-treasure-voyages":{"name":"Zheng He's treasure fleet sets sail","country":"CN","kind":"science","year":1405,"description":"The admiral Zheng He led enormous Ming fleets — some ships several times the size of anything in Europe — across the Indian Ocean as far as East Africa, decades before Columbus.","image":"/events/ming-treasure-voyages.webp","credit":"Photograph by Mike Peel (www.mikepeel.net).","license":"CC BY-SA 4.0"},"forbidden-city":{"name":"The Forbidden City is completed","country":"CN","kind":"engineering","year":1420,"description":"The Yongle Emperor moved the Ming capital to Beijing and into a brand-new walled palace of nearly a thousand buildings. Emperors ruled from it for the next five centuries.","image":"/events/forbidden-city.webp","credit":"N509FZ","license":"CC BY-SA 4.0"},"execution-of-joan-of-arc":{"name":"Joan of Arc is burned at the stake","country":"FR","kind":"conflict","year":1431,"description":"The nineteen-year-old who had turned the Hundred Years' War for France was burned as a heretic in English-held Rouen. A church court annulled the verdict 25 years later; she is now a saint.","image":"/events/execution-of-joan-of-arc.webp","credit":"François Chifflart","license":"Public domain"},"fall-of-constantinople":{"name":"Fall of Constantinople","country":"TR","kind":"conflict","year":1453,"description":"Mehmed II's cannon breached the walls that had held for a thousand years, ending the Byzantine Empire. Constantinople became the Ottoman capital.","image":"/events/fall-of-constantinople.webp","license":"Public domain"},"gutenberg-bible":{"name":"Gutenberg prints his Bible","country":"DE","kind":"science","year":1455,"description":"Johannes Gutenberg finished the first major book printed with movable metal type in Mainz. Printing made books cheap, and cheap books remade Europe.","image":"/events/gutenberg-bible.webp","credit":"Unknown authorUnknown author","license":"CC BY 4.0"},"granada-war":{"name":"Granada falls — the Reconquista ends","country":"ES","kind":"conflict","year":1492,"description":"The last Muslim emirate on the Iberian Peninsula surrendered to Ferdinand and Isabella, ending nearly eight centuries of Reconquista — months before the same monarchs funded Columbus.","image":"/events/granada-war.webp","credit":"Francisco Pradilla y Ortiz","license":"Public domain"},"first-voyage-of-christopher-columbus":{"name":"Columbus reaches the Americas","country":"BS","kind":"science","year":1492,"description":"Sailing west for Asia under the Spanish crown, Columbus made landfall in the Bahamas. He insisted to his death that he had reached the Indies.","image":"/events/first-voyage-of-christopher-columbus.webp","credit":"L. Prang &amp; Co., Boston","license":"Public domain"},"treaty-of-tordesillas":{"name":"Spain and Portugal divide the world","country":"ES","kind":"politics","year":1494,"description":"Spain and Portugal drew a meridian down the Atlantic and split all newly found lands between them. The line is why Brazil speaks Portuguese and most of Latin America Spanish."},"portuguese-discovery-of-the-sea-route-to-india":{"name":"Vasco da Gama reaches India by sea","country":"IN","kind":"science","year":1498,"description":"Vasco da Gama rounded Africa and anchored off Calicut, opening the first all-sea route between Europe and Asia and breaking the overland spice monopoly.","image":"/events/portuguese-discovery-of-the-sea-route-to-india.webp","credit":"Lencer","license":"CC BY-SA 3.0"},"ninety-five-theses":{"name":"Luther posts his Ninety-five Theses","country":"DE","kind":"culture","year":1517,"description":"Martin Luther published ninety-five arguments against the sale of indulgences in Wittenberg. The printing press did the rest — the Reformation split western Christianity.","image":"/events/ninety-five-theses.webp","credit":"Martin Luther","license":"Public domain"},"fall-of-tenochtitlan":{"name":"Fall of Tenochtitlan","country":"MX","kind":"conflict","year":1521,"description":"Cortés, his indigenous allies and a smallpox epidemic brought down the Aztec capital after a brutal siege. Mexico City rose on its ruins.","image":"/events/fall-of-tenochtitlan.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"magellan-expedition":{"name":"The first circumnavigation of the Earth","country":"ES","kind":"science","year":1522,"description":"Of the five ships and roughly 270 men who left Spain, one ship and 18 men returned three years later, having sailed all the way around the world. Magellan himself died in the Philippines.","image":"/events/magellan-expedition.webp","credit":"Abraham Ortelius","license":"Public domain"},"first-battle-of-panipat":{"name":"Babur founds the Mughal Empire","country":"IN","kind":"nation","year":1526,"description":"Babur's cannon and cavalry destroyed the Delhi Sultanate's much larger army at Panipat. The Mughal dynasty he founded ruled most of India into the era of the British.","image":"/events/first-battle-of-panipat.webp","credit":"1598 artist","license":"Public domain"},"battle-of-cajamarca":{"name":"Pizarro captures the Inca emperor","country":"PE","kind":"conflict","year":1532,"description":"Francisco Pizarro ambushed the emperor Atahualpa at Cajamarca with fewer than 200 men. A room full of gold was paid in ransom; Atahualpa was executed anyway, and the Inca Empire fell.","image":"/events/battle-of-cajamarca.webp","credit":"Juan Lepiani","license":"Public domain"},"de-revolutionibus-orbium-coelestium":{"name":"Copernicus puts the Sun at the centre","country":"PL","kind":"science","year":1543,"description":"Copernicus's book placing the Sun, not the Earth, at the centre of the universe was published as he lay dying. It took a century — and Galileo's trial — for the idea to win.","image":"/events/de-revolutionibus-orbium-coelestium.webp","credit":"Mikołaj Kopernik","license":"Public domain"},"great-siege-of-malta":{"name":"Great Siege of Malta","country":"MT","kind":"conflict","year":1565,"description":"A few thousand Knights of St John and Maltese defenders held the island against a massive Ottoman armada for four months. The capital Valletta was founded on the victory.","image":"/events/great-siege-of-malta.webp","credit":"Matteo Perez d'Aleccio","license":"Public domain"},"battle-of-lepanto":{"name":"Battle of Lepanto","country":"GR","kind":"conflict","year":1571,"description":"A Holy League fleet shattered the Ottoman navy off western Greece in the last great battle between rowed galleys. Cervantes lost the use of a hand there, years before writing Don Quixote.","image":"/events/battle-of-lepanto.webp","credit":"Unidentified painter","license":"Public domain"},"spanish-armada":{"name":"The Spanish Armada is defeated","country":"GB","kind":"conflict","year":1588,"description":"Philip II's invasion fleet was beaten in the Channel and wrecked by storms on the long way home around Scotland and Ireland. England stayed Protestant, and stayed uninvaded.","image":"/events/spanish-armada.webp","credit":"anonymous","license":"Public domain"},"battle-of-sekigahara":{"name":"Battle of Sekigahara","country":"JP","kind":"conflict","year":1600,"description":"Tokugawa Ieyasu won the decisive battle for control of Japan. The shogunate his victory founded kept the country at peace — and closed to most of the world — for over 250 years.","image":"/events/battle-of-sekigahara.webp","license":"Public domain"},"dutch-east-india-company":{"name":"The Dutch East India Company is founded","country":"NL","kind":"politics","year":1602,"description":"The Dutch merged their Asia traders into the VOC, the first company to issue shares to the public — armed with its own fleets, forts and colonies.","image":"/events/dutch-east-india-company.webp","credit":"McKarri","license":"CC BY-SA 3.0"},"jamestown":{"name":"Jamestown — England lands in America","country":"US","kind":"nation","year":1607,"description":"The first permanent English settlement in the Americas was planted on a Virginia river island. Two-thirds of the first colonists were dead within a year, but the foothold held.","image":"/events/jamestown.webp","credit":"Peter Vander (via Conway Whittle Sams)","license":"Public domain"},"second-defenestration-of-prague":{"name":"Prague throws its governors out the window","country":"CZ","kind":"conflict","year":1618,"description":"Protestant nobles hurled two imperial governors from a castle window in Prague — they survived the drop — and lit the fuse of the Thirty Years' War, which devastated Central Europe.","image":"/events/second-defenestration-of-prague.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"mayflower":{"name":"The Mayflower sails","country":"US","kind":"nation","year":1620,"description":"A hundred-odd settlers, the Pilgrims among them, crossed from England to Cape Cod aboard the Mayflower, signing a self-government compact before stepping ashore.","image":"/events/mayflower.webp","credit":"William Halsall","license":"Public domain"},"peace-of-westphalia":{"name":"Peace of Westphalia","country":"DE","kind":"politics","year":1648,"description":"The treaties ending the Thirty Years' War fixed the principle that each state is sovereign within its own borders — the operating system of international politics ever since.","image":"/events/peace-of-westphalia.webp","credit":"Gerard ter Borch","license":"Public domain"},"great-fire-of-london":{"name":"Great Fire of London","country":"GB","kind":"disaster","year":1666,"description":"A bakery fire on Pudding Lane burned four-fifths of the walled city over four days, destroying more than 13,000 houses and old St Paul's Cathedral — yet recorded deaths were few.","image":"/events/great-fire-of-london.webp","credit":"Unknown artistUnknown artist","license":"Public domain"},"battle-of-vienna":{"name":"The Ottomans are turned back at Vienna","country":"AT","kind":"conflict","year":1683,"description":"The second and last Ottoman siege of Vienna was broken by a relief army under the Polish king Jan Sobieski, whose winged hussars delivered one of history's largest cavalry charges.","image":"/events/battle-of-vienna.webp","credit":"Juliusz Kossak","license":"Public domain"},"philosophi-naturalis-principia-mathematica":{"name":"Newton publishes the Principia","country":"GB","kind":"science","year":1687,"description":"Newton's Principia set out the laws of motion and universal gravitation — one mathematics for a falling apple and an orbiting Moon.","image":"/events/philosophi-naturalis-principia-mathematica.webp","credit":"The original uploader was Zhaladshar at English Wikisource.","license":"Public domain"},"glorious-revolution":{"name":"Glorious Revolution","country":"GB","kind":"revolution","year":1688,"description":"Parliament's allies invited William of Orange to invade and King James II fled without a battle. The Bill of Rights that followed made the English crown answer to Parliament.","image":"/events/glorious-revolution.webp","credit":"Johan Herman Isings","license":"Public domain"},"saint-petersburg":{"name":"Peter the Great founds Saint Petersburg","country":"RU","kind":"nation","year":1703,"description":"Peter the Great founded a new capital on Baltic marshland seized from Sweden — his \"window to Europe\", built at enormous human cost and modelled on the West.","image":"/events/saint-petersburg.webp","credit":"Florstein (Telegram:WikiPhoto.Space)","license":"CC BY-SA 4.0"},"acts-of-union-1707":{"name":"England and Scotland become Great Britain","country":"GB","kind":"nation","year":1707,"description":"The English and Scottish parliaments voted themselves into a single Kingdom of Great Britain with one parliament at Westminster.","image":"/events/acts-of-union-1707.webp","credit":"Sodacan","license":"CC BY-SA 3.0"},"battle-of-poltava":{"name":"Battle of Poltava","country":"UA","kind":"conflict","year":1709,"description":"Peter the Great destroyed Charles XII's invading Swedish army deep in Ukraine. Sweden's run as a great power ended on that field; Russia's began.","image":"/events/battle-of-poltava.webp","credit":"Pierre-Denis Martin","license":"Public domain"},"1755-lisbon-earthquake":{"name":"1755 Lisbon earthquake","country":"PT","kind":"disaster","year":1755,"description":"An earthquake, tsunami and days of fire destroyed most of Lisbon on All Saints' Day. The catastrophe shook European philosophy — Voltaire wrote Candide in its shadow."},"battle-of-plassey":{"name":"The East India Company takes Bengal","country":"IN","kind":"conflict","year":1757,"description":"Robert Clive's small Company army — helped by a bought-off commander — defeated the Nawab of Bengal at Plassey. A trading company began ruling the richest province in India.","image":"/events/battle-of-plassey.webp","credit":"Francis Hayman","license":"Public domain"},"boston-tea-party":{"name":"Boston Tea Party","country":"US","kind":"revolution","year":1773,"description":"Colonists disguised as Mohawks dumped 342 chests of East India Company tea into Boston Harbor rather than pay Parliament's tax on it. Britain's crackdown pushed the colonies toward war.","image":"/events/boston-tea-party.webp","credit":"Nathaniel Currier","license":"Public domain"},"united-states-declaration-of-independence":{"name":"United States Declaration of Independence","country":"US","kind":"nation","year":1776,"description":"Thirteen British colonies declared themselves free and independent states, resting the claim on the self-evident truth that all men are created equal.","image":"/events/united-states-declaration-of-independence.webp","credit":"original: w:Second Continental Congress; reproduction: William Stone","license":"Public domain"},"sydney":{"name":"The First Fleet reaches Australia","country":"AU","kind":"nation","year":1788,"description":"Eleven British ships carrying around 1,400 people — most of them convicts — anchored at Sydney Cove to found a penal colony, beginning the European settlement of Australia.","image":"/events/sydney.webp","credit":"W. Bulach","license":"CC BY-SA 4.0"},"storming-of-the-bastille":{"name":"Storming of the Bastille","country":"FR","kind":"revolution","year":1789,"description":"A Paris crowd stormed the royal fortress-prison of the Bastille, found just seven prisoners, and started the French Revolution anyway. July 14 is still France's national day.","image":"/events/storming-of-the-bastille.webp","credit":"Jean-Pierre Houël","license":"Public domain"},"haitian-revolution":{"name":"Haitian Revolution","country":"HT","kind":"revolution","year":1791,"description":"The enslaved people of France's richest colony rose, defeated their enslavers and the armies of three empires, and by 1804 had founded Haiti — history's only successful slave revolution to birth a state.","image":"/events/haitian-revolution.webp","credit":"January Suchodolski","license":"Public domain"},"rosetta-stone":{"name":"The Rosetta Stone is found","country":"EG","kind":"science","year":1799,"description":"French soldiers rebuilding a fort in the Nile Delta dug up a slab carrying the same decree in three scripts. It became the key that unlocked Egyptian hieroglyphs.","image":"/events/rosetta-stone.webp","credit":"Awikimate","license":"CC BY-SA 4.0"},"coronation-of-napoleon-i":{"name":"Napoleon crowns himself emperor","country":"FR","kind":"politics","year":1804,"description":"In Notre-Dame, with the Pope watching, Napoleon took the crown and set it on his own head. The republic born of the Revolution had become an empire.","image":"/events/coronation-of-napoleon-i.webp","credit":"Jacques-Louis David","license":"Public domain"},"battle-of-trafalgar":{"name":"Battle of Trafalgar","country":"GB","kind":"conflict","year":1805,"description":"Nelson destroyed the combined French and Spanish fleets off Cape Trafalgar and died aboard Victory in the doing. Britain ruled the waves for the next century.","image":"/events/battle-of-trafalgar.webp","credit":"Nicholas Pocock","license":"Public domain"},"slave-trade-act-1807":{"name":"Britain abolishes the slave trade","country":"GB","kind":"politics","year":1807,"description":"Parliament outlawed the Atlantic slave trade across the British Empire, and the Royal Navy began intercepting slave ships. Slavery itself in the colonies lasted until 1833.","image":"/events/slave-trade-act-1807.webp","credit":"Sodacan","license":"CC BY-SA 3.0"},"french-invasion-of-russia":{"name":"Napoleon marches on Moscow","country":"RU","kind":"conflict","year":1812,"description":"Napoleon led some 600,000 men into Russia and reached a burning, empty Moscow. Winter, hunger and Cossacks destroyed the Grande Armée on the way home — a tenth of it returned.","image":"/events/french-invasion-of-russia.webp","credit":"Blaue Max","license":"CC BY-SA 4.0"},"battle-of-waterloo":{"name":"Battle of Waterloo","country":"BE","kind":"conflict","year":1815,"description":"Escaped from Elba, Napoleon gambled everything on one battle in Belgium and lost it to Wellington and Blücher. He spent his last six years on Saint Helena in the South Atlantic.","image":"/events/battle-of-waterloo.webp","credit":"William Sadler","license":"Public domain"},"congress-of-vienna":{"name":"Congress of Vienna","country":"AT","kind":"politics","year":1815,"description":"Europe's powers redrew the map after Napoleon, restoring monarchs and balancing power. The settlement kept the continent free of a general war for nearly a century.","image":"/events/congress-of-vienna.webp","credit":"Thomas Ledl","license":"CC BY-SA 4.0"},"argentine-declaration-of-independence":{"name":"Argentine Declaration of Independence","country":"AR","kind":"nation","year":1816,"description":"Delegates meeting in Tucumán declared the Provinces of the Río de la Plata independent of Spain, formalising a revolution that had been fighting since 1810.","image":"/events/argentine-declaration-of-independence.webp","credit":"Argentina. Congreso de Tucumán.","license":"Public domain"},"battle-of-boyaca":{"name":"Bolívar frees New Granada","country":"CO","kind":"revolution","year":1819,"description":"Simón Bolívar surprised the Spanish after a brutal march over the Andes and broke their army at Boyacá, freeing Bogotá. Gran Colombia was proclaimed months later.","image":"/events/battle-of-boyaca.webp","credit":"Martin Tovar y Tovar","license":"Public domain"},"greek-war-of-independence":{"name":"Greek War of Independence","country":"GR","kind":"revolution","year":1821,"description":"Greece rose against four centuries of Ottoman rule. Europe's romantics rallied to the cause — Lord Byron died for it — and an independent Greek state emerged within a decade.","image":"/events/greek-war-of-independence.webp","credit":"Louis Dupré","license":"Public domain"},"mexican-war-of-independence":{"name":"Mexico wins independence","country":"MX","kind":"nation","year":1821,"description":"Eleven years after the priest Hidalgo's dawn call to revolt, the Army of the Three Guarantees rode into Mexico City and New Spain became independent Mexico.","image":"/events/mexican-war-of-independence.webp","credit":"Hpav7","license":"Public domain"},"independence-of-brazil":{"name":"Independence of Brazil","country":"BR","kind":"nation","year":1822,"description":"The Portuguese crown prince Pedro, ruling from Rio, declared \"Independence or death!\" on the banks of the Ipiranga and became Brazil's first emperor — independence via the royal family itself.","image":"/events/independence-of-brazil.webp","credit":"Pedro Américo","license":"Public domain"},"battle-of-ayacucho":{"name":"Spanish rule in South America ends","country":"PE","kind":"revolution","year":1824,"description":"Sucre's patriot army defeated the last Spanish royalist force in the Peruvian highlands at Ayacucho, sealing the independence of Spanish South America.","image":"/events/battle-of-ayacucho.webp","credit":"Martín Tovar y Tovar","license":"Public domain"},"stockton-and-darlington-railway":{"name":"The first public steam railway opens","country":"GB","kind":"engineering","year":1825,"description":"The Stockton and Darlington in northern England became the first public railway worked by steam locomotives. Within a generation, railways had shrunk the world.","image":"/events/stockton-and-darlington-railway.webp","credit":"John Dobbin","license":"Public domain"},"belgian-revolution":{"name":"Belgium breaks away","country":"BE","kind":"nation","year":1830,"description":"A revolt that began after an opera performance in Brussels drove out the Dutch and created an independent, neutral Belgium with its own king.","image":"/events/belgian-revolution.webp","credit":"Gustaaf Wappers","license":"Public domain"},"slavery-abolition-act-1833":{"name":"Britain abolishes slavery","country":"GB","kind":"politics","year":1833,"description":"Parliament abolished slavery across most of the British Empire, freeing some 800,000 people — while paying slave-owners, not the enslaved, £20 million in compensation.","image":"/events/slavery-abolition-act-1833.webp","credit":"Sodacan","license":"CC BY-SA 3.0"},"first-opium-war":{"name":"First Opium War","country":"CN","kind":"conflict","year":1839,"description":"China's destruction of British opium stocks brought gunboats. Defeat forced open treaty ports and ceded Hong Kong — the start of what China calls its century of humiliation.","image":"/events/first-opium-war.webp","credit":"Edward Duncan","license":"Public domain"},"treaty-of-waitangi":{"name":"Treaty of Waitangi","country":"NZ","kind":"politics","year":1840,"description":"British officials and some 540 Māori chiefs signed New Zealand's founding document. Its English and Māori texts differ on the crucial word — sovereignty — and the argument continues today.","image":"/events/treaty-of-waitangi.webp","license":"Public domain"},"great-famine-ireland":{"name":"The Great Famine strikes Ireland","country":"IE","kind":"disaster","year":1845,"description":"Potato blight destroyed the crop that fed Ireland's poor. A million people died and over a million emigrated while food exports continued — the island's population has never recovered.","image":"/events/great-famine-ireland.webp","credit":"Illustrated London News, December 22, 1849","license":"Public domain"},"liberian-declaration-of-independence":{"name":"Liberia declares independence","country":"LR","kind":"nation","year":1847,"description":"The West African colony founded for freed Black Americans declared itself a republic — Africa's first — with a constitution and flag modelled on the United States.","image":"/events/liberian-declaration-of-independence.webp","credit":"Government of Liberia","license":"Public domain"},"revolutions-of-1848":{"name":"Revolutions sweep Europe","country":"FR","kind":"revolution","year":1848,"description":"Uprisings toppled the French king and shook thrones from Berlin to Vienna to Palermo in the most widespread revolutionary wave Europe has seen. Nearly all were crushed within a year.","image":"/events/revolutions-of-1848.webp","credit":"Horace Vernet","license":"Public domain"},"the-communist-manifesto":{"name":"The Communist Manifesto","country":"GB","kind":"culture","year":1848,"description":"Marx and Engels published their pamphlet in London weeks before revolution swept Europe. \"Workers of the world, unite!\" went on to reorganise half the planet.","image":"/events/the-communist-manifesto.webp","credit":"Friedrich Engels, Karl Marx","license":"Public domain"},"taiping-rebellion":{"name":"Taiping Rebellion","country":"CN","kind":"revolution","year":1850,"description":"A failed exam candidate who believed himself the younger brother of Jesus raised a rebel Heavenly Kingdom against the Qing. The fourteen-year civil war killed some twenty million people.","image":"/events/taiping-rebellion.webp","credit":"M.Bitton","license":"CC BY-SA 4.0"},"great-exhibition":{"name":"The Great Exhibition opens in the Crystal Palace","country":"GB","kind":"culture","year":1851,"description":"The first world's fair filled a vast prefabricated glass hall in Hyde Park with the machines and goods of the industrial age. Six million people came — a third of Britain's population.","image":"/events/great-exhibition.webp","credit":"Dickinson Brothers","license":"Public domain"},"crimean-war":{"name":"Crimean War","country":"UA","kind":"conflict","year":1853,"description":"Britain, France and the Ottomans fought Russia, mostly on the Crimean peninsula. It gave the world the Charge of the Light Brigade, war photography and Florence Nightingale's nursing reforms.","image":"/events/crimean-war.webp","credit":"British Army official photographer","license":"Public domain"},"indian-rebellion-of-1857":{"name":"Indian Rebellion of 1857","country":"IN","kind":"revolution","year":1857,"description":"Sepoy regiments rose against the East India Company and the revolt spread across northern India. After its brutal suppression, the British Crown took direct rule of India from the Company.","image":"/events/indian-rebellion-of-1857.webp","license":"Public domain"},"on-the-origin-of-species":{"name":"Darwin publishes On the Origin of Species","country":"GB","kind":"science","year":1859,"description":"Darwin's book laid out evolution by natural selection after twenty years of hesitation. The first print run sold out to booksellers on day one.","image":"/events/on-the-origin-of-species.webp","credit":"John Murray, Publisher","license":"Public domain"},"kingdom-of-italy":{"name":"Italy is unified","country":"IT","kind":"nation","year":1861,"description":"After Garibaldi's thousand red-shirted volunteers took the south, the Kingdom of Italy was proclaimed under Victor Emmanuel II — the peninsula's first single state since Rome. Venice and Rome itself joined within a decade.","image":"/events/kingdom-of-italy.webp","credit":"F l a n k e r","license":"Public domain"},"american-civil-war":{"name":"American Civil War","country":"US","kind":"conflict","year":1861,"description":"Eleven slave states seceded and the Union fought them back over four years — the deadliest war in American history. It ended slavery by the Thirteenth Amendment.","image":"/events/american-civil-war.webp","credit":"Nathaniel Currier and James Merritt Ives","license":"Public domain"},"emancipation-reform-of-1861":{"name":"Russia frees the serfs","country":"RU","kind":"politics","year":1861,"description":"Tsar Alexander II emancipated more than twenty million serfs — bound peasants who could be bought and sold with the land. Freedom came with debts that kept most of them poor.","image":"/events/emancipation-reform-of-1861.webp","credit":"Boris Kustodiev","license":"Public domain"},"international-committee-of-the-red-cross":{"name":"The Red Cross is founded","country":"CH","kind":"politics","year":1863,"description":"Horrified by the untended wounded at Solferino, the Geneva businessman Henry Dunant founded the Red Cross. The first Geneva Convention followed a year later.","image":"/events/international-committee-of-the-red-cross.webp","credit":"Torbjorn Toby Jorgensen","license":"CC BY-SA 2.0"},"alaska-purchase":{"name":"The United States buys Alaska","country":"US","kind":"politics","year":1867,"description":"Russia sold Alaska to the United States for $7.2 million — about two cents an acre. Critics called it \"Seward's Folly\" until the gold and oil turned up.","image":"/events/alaska-purchase.webp","credit":"Edouard de Stoeckl and William H. Seward","license":"Public domain"},"canadian-confederation":{"name":"Canadian Confederation","country":"CA","kind":"nation","year":1867,"description":"Three British North American colonies federated into the Dominion of Canada — a country assembled by conference and statute rather than revolution.","image":"/events/canadian-confederation.webp","credit":"No machine-readable author provided. Golbez assumed (based on copyright claims).","license":"CC BY 2.5"},"meiji-restoration":{"name":"Meiji Restoration","country":"JP","kind":"revolution","year":1868,"description":"Samurai from the southwest toppled the shogunate and restored the young Meiji emperor. Japan then industrialised at a sprint, going from feudal isolation to great power in one generation.","image":"/events/meiji-restoration.webp","credit":"Alfred Roussin","license":"Public domain"},"suez-canal":{"name":"The Suez Canal opens","country":"EG","kind":"engineering","year":1869,"description":"Ten years of digging joined the Mediterranean to the Red Sea, cutting the Europe–Asia voyage by weeks. Verdi's Aida was commissioned for the Cairo opera house that opened alongside it.","image":"/events/suez-canal.webp","credit":"Pierre Markuse from Hamm, Germany","license":"CC BY 2.0"},"first-transcontinental-railroad":{"name":"America's coasts are joined by rail","country":"US","kind":"engineering","year":1869,"description":"A golden spike at Promontory Summit, Utah joined the tracks built east from Sacramento and west from Omaha. A months-long wagon crossing became a week by train.","image":"/events/first-transcontinental-railroad.webp","credit":"Andrew J. Russell (1830-1902), photographer","license":"Public domain"},"paris-commune":{"name":"Paris Commune","country":"FR","kind":"revolution","year":1871,"description":"After France's defeat by Prussia, Paris rose and governed itself as a radical commune for 72 days before the army retook the city street by street, killing thousands in Bloody Week.","image":"/events/paris-commune.webp","credit":"Anonyme, photographe","license":"CC0"},"unification-of-germany":{"name":"Germany is unified","country":"DE","kind":"nation","year":1871,"description":"After Prussia's victory over France, the German Empire was proclaimed — pointedly — in the Hall of Mirrors at Versailles, with the Prussian king as Kaiser and Bismarck as chancellor.","image":"/events/unification-of-germany.webp","credit":"Anton von Werner","license":"Public domain"},"berlin-conference":{"name":"Europe carves up Africa","country":"DE","kind":"politics","year":1884,"description":"European powers met in Berlin to set the rules for claiming African territory — no African was at the table. Within two decades the continent was almost entirely colonised.","image":"/events/berlin-conference.webp","credit":"Adalbert von Roessler","license":"Public domain"},"1883-eruption-of-krakatoa":{"name":"1883 eruption of Krakatoa","country":"ID","kind":"disaster","year":1883,"description":"The island volcano between Java and Sumatra blew itself apart with a blast heard 4,800 kilometres away. Its tsunamis killed tens of thousands, and its dust reddened sunsets worldwide for years.","image":"/events/1883-eruption-of-krakatoa.webp","credit":"AnonymousUnknown author","license":"Public domain"},"statue-of-liberty":{"name":"The Statue of Liberty is dedicated","country":"US","kind":"engineering","year":1886,"description":"France's copper colossus — designed by Bartholdi, engineered inside by Eiffel — was unveiled in New York Harbor, greeting the greatest wave of immigration in American history.","image":"/events/statue-of-liberty.webp","credit":"Christian David","license":"CC BY-SA 4.0"},"lei-aurea":{"name":"Brazil abolishes slavery","country":"BR","kind":"politics","year":1888,"description":"Princess Isabel signed the Golden Law, freeing Brazil's remaining enslaved people with a single sentence. Brazil was the last country in the Americas to abolish slavery.","image":"/events/lei-aurea.webp","credit":"Valter Campanato/Agência Brasil","license":"CC BY 2.0"},"eiffel-tower":{"name":"The Eiffel Tower opens","country":"FR","kind":"engineering","year":1889,"description":"Built as the entrance arch to the 1889 World's Fair and meant to stand twenty years, it was then the tallest structure on Earth. Paris's artists petitioned furiously against it.","image":"/events/eiffel-tower.webp","credit":"Benh LIEU SONG","license":"Public domain"},"battle-of-adwa":{"name":"Ethiopia defeats an invading empire","country":"ET","kind":"conflict","year":1896,"description":"Emperor Menelik II's army routed the invading Italians at Adwa. Ethiopia became the great exception of the colonial age — an African state that beat a European power and kept its independence.","image":"/events/battle-of-adwa.webp","license":"CC BY-SA 3.0"},"1896-summer-olympics":{"name":"The first modern Olympics","country":"GR","kind":"culture","year":1896,"description":"The Olympic Games returned after fifteen centuries, staged in Athens with 14 nations. A Greek water-carrier, Spyridon Louis, won the first marathon and became a national hero.","image":"/events/1896-summer-olympics.webp","credit":"Docpix","license":"Public domain"},"klondike-gold-rush":{"name":"Klondike Gold Rush","country":"CA","kind":"culture","year":1896,"description":"Gold found in a Yukon creek sent a hundred thousand stampeders over frozen mountain passes toward Dawson City. Most arrived to find the good claims long staked.","image":"/events/klondike-gold-rush.webp","credit":"Eric A. Hegg","license":"Public domain"},"spanish-american-war":{"name":"Spanish–American War","country":"CU","kind":"conflict","year":1898,"description":"A ten-week war fought over Cuba ended Spain's empire in the Americas and the Pacific. The United States emerged with Puerto Rico, Guam and the Philippines — a colonial power itself.","image":"/events/spanish-american-war.webp","credit":"Barbudo Barbudo and TEP","license":"CC BY-SA 4.0"},"second-boer-war":{"name":"Second Boer War","country":"ZA","kind":"conflict","year":1899,"description":"Britain fought the Boer republics for three years over southern Africa and its gold. The war introduced the world to the term \"concentration camp\", where tens of thousands died.","image":"/events/second-boer-war.webp","credit":"Reinhold Thiele","license":"Public domain"},"boxer-rebellion":{"name":"Boxer Rebellion","country":"CN","kind":"revolution","year":1900,"description":"An anti-foreign uprising besieged Beijing's diplomatic quarter for 55 days until an eight-nation army marched on the capital. The indemnities imposed helped bring down the Qing a decade later."},"federation-of-australia":{"name":"Federation of Australia","country":"AU","kind":"nation","year":1901,"description":"Six self-governing British colonies federated into the Commonwealth of Australia on the first day of the new century — nationhood by referendum rather than revolution."},"nobel-prize":{"name":"The first Nobel Prizes are awarded","country":"SE","kind":"culture","year":1901,"description":"The fortune of Alfred Nobel — the inventor of dynamite — funded the first prizes for physics, chemistry, medicine, literature and peace, awarded in Stockholm and Oslo.","image":"/events/nobel-prize.webp","credit":"Nobel Foundation, diploma by Sofia Gisberg[1]","license":"Public domain"},"wright-flyer":{"name":"The Wright brothers fly","country":"US","kind":"science","year":1903,"description":"On a North Carolina beach, the Wright brothers made the first controlled, powered aeroplane flights. The longest of the day covered 260 metres — less than a modern jet's wingspan-to-tail walk.","image":"/events/wright-flyer.webp","credit":"John T. Daniels","license":"Public domain"},"russo-japanese-war":{"name":"Russo-Japanese War","country":"JP","kind":"conflict","year":1904,"description":"Japan fought Russia over Korea and Manchuria and won on land and at sea, annihilating the Baltic Fleet at Tsushima — the first modern defeat of a European great power by an Asian one.","image":"/events/russo-japanese-war.webp","credit":"Original uploader and author was Dustandshadow at en.wikipedia","license":"Public domain"},"dissolution-of-the-union-between-norway-and-sweden":{"name":"Norway leaves its union with Sweden","country":"NO","kind":"nation","year":1905,"description":"Norway voted itself out of the union with Sweden — 368,208 for, 184 against — and both sides let it happen peacefully. A Danish prince became King Haakon VII."},"1906-san-francisco-earthquake":{"name":"1906 San Francisco earthquake","country":"US","kind":"disaster","year":1906,"description":"The earthquake and the three days of fire that followed destroyed most of San Francisco, leaving over half the city's population homeless.","image":"/events/1906-san-francisco-earthquake.webp","credit":"Chadwick, H. D","license":"Public domain"},"young-turk-revolution":{"name":"Young Turk Revolution","country":"TR","kind":"revolution","year":1908,"description":"Army officers of the Young Turk movement forced the sultan to restore the constitution and parliament, beginning the Ottoman Empire's last, turbulent decade."},"mexican-revolution":{"name":"Mexican Revolution","country":"MX","kind":"revolution","year":1910,"description":"What began as a revolt against the thirty-year rule of Porfirio Díaz became a decade of civil war — Zapata and Villa among its generals — that killed perhaps a million Mexicans.","image":"/events/mexican-revolution.webp","credit":"Rαge","license":"CC BY-SA 3.0"},"amundsen-s-south-pole-expedition":{"name":"Amundsen reaches the South Pole","country":"NO","kind":"science","year":1911,"description":"Roald Amundsen's ski-and-dog-sled team reached the South Pole five weeks ahead of Robert Scott, whose entire party died on the return march."},"xinhai-revolution":{"name":"China's last dynasty falls","country":"CN","kind":"revolution","year":1911,"description":"A mutiny at Wuchang cascaded into national revolution, and within months the six-year-old Puyi abdicated. Two thousand years of imperial rule ended; the Republic of China began.","image":"/events/xinhai-revolution.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"sinking-of-the-titanic":{"name":"Sinking of the Titanic","country":"GB","kind":"disaster","year":1912,"description":"The largest ship afloat, promoted as practically unsinkable, struck an iceberg on her maiden voyage and sank with around 1,500 people — lifeboats had seats for barely half of those aboard.","image":"/events/sinking-of-the-titanic.webp","credit":"Ziko van Dijk","license":"CC BY-SA 4.0"},"panama-canal":{"name":"The Panama Canal opens","country":"PA","kind":"engineering","year":1914,"description":"The canal cut through the isthmus joined the Atlantic and Pacific, sparing ships the 13,000-kilometre voyage around Cape Horn. France had tried first and lost some 20,000 workers to disease.","image":"/events/panama-canal.webp","credit":"User:Stan Shebs","license":"CC BY-SA 3.0"},"assassination-of-archduke-franz-ferdinand":{"name":"Shots at Sarajevo — the spark of WWI","country":"BA","kind":"conflict","year":1914,"description":"A Bosnian Serb student shot the Austro-Hungarian heir and his wife in Sarajevo. Five weeks of ultimatums and mobilisations later, most of Europe was at war.","image":"/events/assassination-of-archduke-franz-ferdinand.webp","credit":"Achille Beltrame","license":"Public domain"},"gallipoli-campaign":{"name":"Gallipoli campaign","country":"TR","kind":"conflict","year":1915,"description":"The Allied attempt to force the Dardanelles and take Constantinople died on the Gallipoli beaches. The defence made Mustafa Kemal's name; the landings are founding memory for Australia and New Zealand."},"armenian-genocide":{"name":"Armenian genocide","country":"AM","kind":"conflict","year":1915,"description":"The Ottoman government deported the empire's Armenians into the Syrian desert through massacre and death march, killing perhaps a million or more. The word \"genocide\" was later coined largely for it.","image":"/events/armenian-genocide.webp","credit":"Henry Morgenthau","license":"Public domain"},"easter-rising":{"name":"Easter Rising","country":"IE","kind":"revolution","year":1916,"description":"Irish republicans seized central Dublin and proclaimed a republic from the General Post Office. The rising was crushed in six days, but the execution of its leaders turned the country against British rule.","image":"/events/easter-rising.webp","credit":"Miller, James Martin &amp; H.S. Canfield.","license":"Public domain"},"october-revolution":{"name":"October Revolution","country":"RU","kind":"revolution","year":1917,"description":"Lenin's Bolsheviks seized Petrograd's key points and the Winter Palace in a nearly bloodless coup, eight months after the tsar had fallen. The world's first communist state followed.","image":"/events/october-revolution.webp","credit":"Pyotr Novitsky","license":"Public domain"},"finnish-declaration-of-independence":{"name":"Finland declares independence","country":"FI","kind":"nation","year":1917,"description":"As revolutionary Russia collapsed, Finland's parliament declared independence after a century as a Russian grand duchy — recognised, remarkably, by Lenin's new government within a month.","image":"/events/finnish-declaration-of-independence.webp","credit":"Senate of Finland","license":"Public domain"},"armistice-of-11-november-1918":{"name":"The Armistice ends the First World War","country":"FR","kind":"conflict","year":1918,"description":"In a railway carriage in the forest of Compiègne, the guns of the First World War fell silent at the eleventh hour of the eleventh day of the eleventh month. Some 17 million people were dead.","image":"/events/armistice-of-11-november-1918.webp","credit":"Maurice Pillard Verneuil","license":"Public domain"},"spanish-flu":{"name":"The 1918 flu pandemic","country":"US","kind":"disaster","year":1918,"description":"The influenza pandemic of 1918 infected a third of humanity and killed at least 50 million — more than the war it rode in on. It was called \"Spanish\" only because Spain's uncensored press reported it first.","image":"/events/spanish-flu.webp","credit":"Otis Historical Archives, National Museum of Health and Medicine","license":"Public domain"},"treaty-of-versailles":{"name":"Treaty of Versailles","country":"FR","kind":"politics","year":1919,"description":"The peace signed in the Hall of Mirrors stripped Germany of territory and empire and billed it for the war. Its \"war guilt\" terms became tinder for the next one.","image":"/events/treaty-of-versailles.webp","credit":"David Lloyd George, Woodrow Wilson and Georges Clemenceau","license":"Public domain"},"jallianwala-bagh-massacre":{"name":"Jallianwala Bagh massacre","country":"IN","kind":"conflict","year":1919,"description":"British troops fired without warning into a trapped crowd in a walled garden in Amritsar, killing hundreds. The massacre broke Indian faith in the empire and swelled the independence movement.","image":"/events/jallianwala-bagh-massacre.webp","credit":"PP Yoonus (ppyoonus@yahoo.co.in)","license":"Public domain"},"league-of-nations":{"name":"The League of Nations convenes","country":"CH","kind":"politics","year":1920,"description":"The first world organisation for collective security assembled in Geneva — without the United States, whose Senate refused to join the body its own president had championed.","image":"/events/league-of-nations.webp","credit":"Maps &amp; Lucy","license":"CC BY-SA 3.0"},"anglo-irish-treaty":{"name":"The Irish Free State is born","country":"IE","kind":"nation","year":1921,"description":"The treaty ending the Irish War of Independence created a self-governing Free State of 26 counties, with six remaining British. The split over its terms led straight into civil war."},"march-on-rome":{"name":"Mussolini takes power","country":"IT","kind":"revolution","year":1922,"description":"Mussolini's blackshirts converged on the capital and the king, rather than order the army to stop them, invited the Fascist leader to form a government. Europe had its first fascist state.","image":"/events/march-on-rome.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"tomb-of-tutankhamun":{"name":"Tutankhamun's tomb is opened","country":"EG","kind":"science","year":1922,"description":"Howard Carter found the one royal tomb in the Valley of the Kings that robbers had barely touched. Asked if he could see anything through the breach, he answered: \"Yes, wonderful things.\"","image":"/events/tomb-of-tutankhamun.webp","credit":"EditorfromMars","license":"CC BY-SA 4.0"},"soviet-union":{"name":"The Soviet Union is formed","country":"RU","kind":"nation","year":1922,"description":"Russia, Ukraine, Belarus and the Transcaucasus signed themselves into the Union of Soviet Socialist Republics — on paper a federation, in practice ruled from Moscow. It lasted 69 years.","image":"/events/soviet-union.webp","credit":"Cmapm","license":"CC BY-SA 3.0"},"1923-great-kanto-earthquake":{"name":"1923 Great Kantō earthquake","country":"JP","kind":"disaster","year":1923,"description":"The earthquake and firestorms that followed destroyed Tokyo and Yokohama, killing over 100,000 people — Japan's deadliest disaster, struck at lunchtime while the city's stoves were lit.","image":"/events/1923-great-kanto-earthquake.webp","license":"Public domain"},"republic-of-turkiye":{"name":"Atatürk proclaims the Turkish republic","country":"TR","kind":"nation","year":1923,"description":"From the Ottoman Empire's ruins, Mustafa Kemal — later Atatürk, \"father of the Turks\" — proclaimed a republic with its capital at Ankara, then remade alphabet, dress and law at speed.","image":"/events/republic-of-turkiye.webp","credit":"Jorge Franganillo from Barcelona, Spain","license":"CC BY 2.0"},"discovery-of-penicillin":{"name":"Fleming discovers penicillin","country":"GB","kind":"science","year":1928,"description":"Alexander Fleming returned from holiday to find mould killing the bacteria on a neglected culture plate. The antibiotic age it opened has saved hundreds of millions of lives."},"wall-street-crash-of-1929":{"name":"Wall Street Crash of 1929","country":"US","kind":"disaster","year":1929,"description":"The New York stock market collapsed over a handful of October days, erasing fortunes and confidence together. The Great Depression that followed put a quarter of Americans out of work.","image":"/events/wall-street-crash-of-1929.webp","credit":"US-gov","license":"Public domain"},"salt-march":{"name":"Gandhi marches to the sea for salt","country":"IN","kind":"revolution","year":1930,"description":"Gandhi walked 385 kilometres to the sea and picked up a handful of salt, breaking the British monopoly law. The gesture ignited mass civil disobedience across India.","image":"/events/salt-march.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"1930-fifa-world-cup":{"name":"The first football World Cup","country":"UY","kind":"culture","year":1930,"description":"Uruguay hosted and won the first World Cup, beating Argentina 4–2 in Montevideo. Only thirteen teams came — every European entrant had to be talked into the boat journey."},"empire-state-building":{"name":"The Empire State Building opens","country":"US","kind":"engineering","year":1931,"description":"Built in a Depression-defying 13 months, the 102-storey tower took the title of world's tallest building and held it for four decades.","image":"/events/empire-state-building.webp","credit":"Sam Valadi","license":"Public domain"},"siamese-revolution-of-1932":{"name":"Siam ends absolute monarchy","country":"TH","kind":"revolution","year":1932,"description":"A bloodless dawn coup by young officers and officials ended seven centuries of absolute monarchy in Siam, forcing the king to accept a constitution.","image":"/events/siamese-revolution-of-1932.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"machtergreifung":{"name":"Hitler comes to power","country":"DE","kind":"revolution","year":1933,"description":"Hitler was appointed chancellor by President Hindenburg, and within months the Nazis had burned out the Reichstag opposition, banned rival parties and ruled by decree.","image":"/events/machtergreifung.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"long-march":{"name":"Long March","country":"CN","kind":"conflict","year":1934,"description":"Encircled by Nationalist armies, the Chinese communists broke out and marched some 9,000 kilometres over mountains and rivers to a new base at Yan'an. Mao emerged from it as the party's leader.","image":"/events/long-march.webp","license":"CC BY-SA 3.0"},"second-italo-ethiopian-war":{"name":"Italy invades Ethiopia","country":"ET","kind":"conflict","year":1935,"description":"Mussolini invaded Ethiopia with tanks, bombers and poison gas, avenging Adwa forty years on. The League of Nations' failure to stop it exposed collective security as a dead letter.","image":"/events/second-italo-ethiopian-war.webp","credit":"Achille Beltrame","license":"Public domain"},"spanish-civil-war":{"name":"Spanish Civil War","country":"ES","kind":"conflict","year":1936,"description":"A generals' rising against the republic tore Spain apart for three years, with Hitler and Mussolini arming Franco and volunteers from fifty countries fighting for the other side. Franco's dictatorship lasted until 1975.","image":"/events/spanish-civil-war.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"golden-gate-bridge":{"name":"The Golden Gate Bridge opens","country":"US","kind":"engineering","year":1937,"description":"The longest suspension span yet built crossed the fog-swept strait at the mouth of San Francisco Bay. Its \"international orange\" paint was meant to be temporary.","image":"/events/golden-gate-bridge.webp","credit":"Rich Niewiroski Jr.","license":"CC BY 2.5"},"hindenburg-disaster":{"name":"Hindenburg disaster","country":"US","kind":"disaster","year":1937,"description":"The hydrogen-filled German airship burst into flames while landing in New Jersey, killing 36 — with newsreel cameras rolling. The age of the great passenger airships ended in that minute.","image":"/events/hindenburg-disaster.webp","credit":"Sam Shere","license":"Public domain"},"nanjing-massacre":{"name":"Nanjing Massacre","country":"CN","kind":"conflict","year":1937,"description":"After the fall of China's capital, Japanese troops spent weeks massacring prisoners and civilians and raping tens of thousands. The death toll is contested; the horror is not.","image":"/events/nanjing-massacre.webp","credit":"Originally Moriyasu Murase, 村瀬守保","license":"Public domain"},"kristallnacht":{"name":"Kristallnacht","country":"DE","kind":"conflict","year":1938,"description":"In a single organised November night, Nazi mobs burned over a thousand synagogues and smashed Jewish shops and homes across Germany and Austria. The name mocks the broken glass in the streets.","image":"/events/kristallnacht.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"invasion-of-poland":{"name":"The Second World War begins","country":"PL","kind":"conflict","year":1939,"description":"Germany invaded Poland from the west; the Soviet Union followed from the east under their secret pact. Britain and France declared war on Germany two days in — the Second World War had begun.","image":"/events/invasion-of-poland.webp","license":"Public domain"},"battle-of-britain":{"name":"Battle of Britain","country":"GB","kind":"conflict","year":1940,"description":"The Luftwaffe spent a summer trying to break the RAF as the prelude to invasion, and failed — the war's first check on Germany. \"Never was so much owed by so many to so few.\"","image":"/events/battle-of-britain.webp","credit":"German Air Force photographer","license":"Public domain"},"attack-on-pearl-harbor":{"name":"Attack on Pearl Harbor","country":"US","kind":"conflict","year":1941,"description":"Japanese carrier aircraft struck the US Pacific Fleet at anchor in Hawaii on a Sunday morning, sinking battleships and killing over 2,400 Americans. The United States entered the war the next day.","image":"/events/attack-on-pearl-harbor.webp","credit":"Unknown navy photographer","license":"Public domain"},"battle-of-stalingrad":{"name":"Battle of Stalingrad","country":"RU","kind":"conflict","year":1942,"description":"The Wehrmacht bled out in five months of street fighting on the Volga, and the encircled Sixth Army surrendered in the ruins. It was the turning point of the war in Europe.","image":"/events/battle-of-stalingrad.webp","credit":"Abram Krichevsky (Q4241405) / TASS (Q223799)","license":"Public domain"},"normandy-landings":{"name":"D-Day — the Allies land in Normandy","country":"FR","kind":"conflict","year":1944,"description":"On 6 June 1944, some 156,000 Allied troops crossed the Channel onto five Normandy beaches in history's largest seaborne invasion. Paris was free by August.","image":"/events/normandy-landings.webp","credit":"Chief Photographer's Mate (CPHoM) Robert F. Sargent","license":"Public domain"},"bretton-woods-conference":{"name":"Bretton Woods Conference","country":"US","kind":"politics","year":1944,"description":"Delegates from 44 Allied nations, meeting at a New Hampshire resort hotel, designed the postwar money system — fixed exchange rates, the IMF and the World Bank.","image":"/events/bretton-woods-conference.webp","credit":"Barry Livingstone","license":"CC BY-SA 3.0"},"iceland":{"name":"Iceland becomes a republic","country":"IS","kind":"nation","year":1944,"description":"With Denmark under German occupation, Icelanders voted almost unanimously to dissolve the union with the Danish crown and founded a republic at Þingvellir, seat of their thousand-year-old assembly.","image":"/events/iceland.webp","credit":"European Space Agency","license":"Attribution"},"atomic-bombings-of-hiroshima-and-nagasaki":{"name":"Atomic bombs fall on Japan","country":"JP","kind":"conflict","year":1945,"description":"The first nuclear weapons used in war destroyed Hiroshima and, three days later, Nagasaki, killing well over a hundred thousand people by year's end. Japan surrendered within a week of the second bomb.","image":"/events/atomic-bombings-of-hiroshima-and-nagasaki.webp","credit":"George R. Caron / Charles Levy","license":"Public domain"},"united-nations":{"name":"The United Nations is founded","country":"US","kind":"politics","year":1945,"description":"Fifty-one nations signed the UN Charter in San Francisco, determined — its opening words say — \"to save succeeding generations from the scourge of war\".","image":"/events/united-nations.webp","credit":"U.S. Department of State from United States","license":"Public domain"},"nuremberg-trials":{"name":"Nuremberg trials","country":"DE","kind":"politics","year":1945,"description":"The surviving Nazi leadership was tried by an international tribunal in Nuremberg for crimes against humanity — the founding precedent that following orders is no defence.","image":"/events/nuremberg-trials.webp","credit":"Raymond D’Addario","license":"Public domain"},"treaty-of-manila-1946":{"name":"The Philippines becomes independent","country":"PH","kind":"nation","year":1946,"description":"The United States recognised Philippine independence on 4 July 1946, closing nearly half a century of American rule that had followed three centuries of Spanish rule."},"partition-of-india":{"name":"India and Pakistan are born","country":"IN","kind":"nation","year":1947,"description":"British India was split at midnight into independent India and Pakistan. The partition uprooted some 15 million people along hastily drawn lines and killed perhaps a million in the violence.","image":"/events/partition-of-india.webp","credit":"Own work","license":"CC BY-SA 4.0"},"marshall-plan":{"name":"Marshall Plan","country":"US","kind":"politics","year":1948,"description":"The United States poured about $13 billion into rebuilding Western Europe's shattered economies — and binding them to the West as the Cold War hardened."},"assassination-of-mahatma-gandhi":{"name":"Assassination of Mahatma Gandhi","country":"IN","kind":"politics","year":1948,"description":"Five months into independence, Gandhi was shot dead at his evening prayer meeting in Delhi by a Hindu nationalist who blamed him for partition and for conciliating Muslims.","image":"/events/assassination-of-mahatma-gandhi.webp","credit":"Wilson Loo Kok Wee","license":"CC BY-SA 2.0"},"israeli-declaration-of-independence":{"name":"The State of Israel is declared","country":"IL","kind":"nation","year":1948,"description":"David Ben-Gurion proclaimed the State of Israel in Tel Aviv as the British mandate expired. Five Arab armies crossed the borders the next day; the war's displacements shape the region still.","image":"/events/israeli-declaration-of-independence.webp","credit":"Rudi Weissenstein","license":"Public domain"},"berlin-blockade":{"name":"The Berlin Airlift begins","country":"DE","kind":"conflict","year":1948,"description":"The Soviets cut every road and rail line into West Berlin, and the Western allies fed two million people by air for eleven months — a plane landing roughly every minute at the peak.","image":"/events/berlin-blockade.webp","credit":"Heilig, Walter","license":"CC BY-SA 3.0 de"},"universal-declaration-of-human-rights":{"name":"Universal Declaration of Human Rights","country":"FR","kind":"politics","year":1948,"description":"The UN General Assembly, meeting in Paris, adopted thirty articles of rights belonging to every human being — drafted by a committee chaired by Eleanor Roosevelt.","image":"/events/universal-declaration-of-human-rights.webp","credit":"FDR Presidential Library &amp; Museum","license":"CC BY 2.0"},"nato":{"name":"NATO is founded","country":"US","kind":"politics","year":1949,"description":"Twelve North Atlantic nations signed a treaty in Washington making an attack on one an attack on all. Article 5 has been invoked once — after September 11.","image":"/events/nato.webp","credit":"Влада на Република Северна Македонија","license":"Public domain"},"proclamation-of-the-people-s-republic-of-china":{"name":"Proclamation of the People's Republic of China","country":"CN","kind":"nation","year":1949,"description":"From the Tiananmen gate, Mao proclaimed the People's Republic after the communists' civil-war victory. The defeated Nationalists withdrew to Taiwan — both governments still claim to be China.","image":"/events/proclamation-of-the-people-s-republic-of-china.webp","credit":"Orihara1","license":"Public domain"},"korean-war":{"name":"Korean War","country":"KR","kind":"conflict","year":1950,"description":"North Korea invaded the South and a UN force led by the United States fought it — and then China — to a stalemate near where the war began. An armistice, never a peace treaty, holds the line today.","image":"/events/korean-war.webp","credit":"All photographs are works of the United States federal government.","license":"Public domain"},"egyptian-revolution-of-1952":{"name":"The Free Officers topple Egypt's king","country":"EG","kind":"revolution","year":1952,"description":"Army officers led by Nasser and Naguib deposed King Farouk in a night, ending the monarchy and British-era rule. Nasser's Egypt became the pole star of Arab nationalism."},"1953-british-mount-everest-expedition":{"name":"Everest is climbed","country":"NP","kind":"science","year":1953,"description":"Edmund Hillary and Tenzing Norgay stood on the summit of Everest on 29 May 1953 — the first people on the highest point on Earth. News reached London on Coronation morning.","image":"/events/1953-british-mount-everest-expedition.webp","credit":"Pavel Novak","license":"CC BY-SA 2.5"},"molecular-structure-of-nucleic-acids-a-structure-for-deoxyribose-nucleic-acid":{"name":"The DNA double helix is revealed","country":"GB","kind":"science","year":1953,"description":"Watson and Crick published DNA's double-helix structure, built on Rosalind Franklin's X-ray images. The paper's closing understatement — the structure \"suggests a possible copying mechanism\" — opened modern genetics."},"battle-of-dien-bien-phu":{"name":"France falls at Dien Bien Phu","country":"VN","kind":"conflict","year":1954,"description":"The Viet Minh dragged artillery up jungle mountains and crushed the French garrison in its valley fortress. French Indochina ended at the conference table weeks later, with Vietnam divided at the 17th parallel.","image":"/events/battle-of-dien-bien-phu.webp","credit":"Vietnam People's Army","license":"Public domain"},"warsaw-pact":{"name":"Warsaw Pact","country":"PL","kind":"politics","year":1955,"description":"The Soviet Union bound its Eastern European satellites into a military alliance answering NATO. Its only joint invasion was of one of its own members — Czechoslovakia, 1968.","image":"/events/warsaw-pact.webp","credit":"愛喝奶茶","license":"CC BY-SA 4.0"},"montgomery-bus-boycott":{"name":"Rosa Parks keeps her seat","country":"US","kind":"culture","year":1955,"description":"Rosa Parks was arrested for refusing to give up her bus seat, and Black Montgomery walked for 381 days until the buses were desegregated. The boycott's young spokesman was Martin Luther King Jr.","image":"/events/montgomery-bus-boycott.webp","credit":"Rmhermen","license":"CC BY-SA 3.0"},"bandung-conference":{"name":"Bandung Conference","country":"ID","kind":"politics","year":1955,"description":"Twenty-nine newly independent Asian and African states met in Bandung to chart a course between the Cold War blocs — the seedbed of the Non-Aligned Movement.","image":"/events/bandung-conference.webp","credit":"Foreign Ministry of the Republic of Indonesia","license":"Public domain"},"hungarian-revolution-of-1956":{"name":"Hungarian Revolution of 1956","country":"HU","kind":"revolution","year":1956,"description":"Budapest rose against Soviet rule and for a few days Hungary was free — until the tanks returned. Thousands died and 200,000 fled west while the world watched.","image":"/events/hungarian-revolution-of-1956.webp","credit":"Atoljaka","license":"CC BY 4.0"},"suez-crisis":{"name":"Suez Crisis","country":"EG","kind":"conflict","year":1956,"description":"When Nasser nationalised the Suez Canal, Britain, France and Israel invaded — and were forced out by American and Soviet pressure. The end of empire had a date on it after Suez.","image":"/events/suez-crisis.webp","credit":"United States Army Heritage and Education Center","license":"Public domain"},"independence-of-ghana":{"name":"Ghana leads Africa to independence","country":"GH","kind":"nation","year":1957,"description":"The Gold Coast became Ghana under Kwame Nkrumah — the first sub-Saharan colony to win independence. \"Our independence is meaningless,\" he said that night, \"unless it is linked up with the total liberation of Africa.\"","image":"/events/independence-of-ghana.webp","credit":"Sodacan","license":"CC BY-SA 3.0"},"treaty-of-rome":{"name":"Six nations found the Common Market","country":"IT","kind":"politics","year":1957,"description":"France, West Germany, Italy and the Benelux countries signed the Treaty of Rome, creating the European Economic Community — the six-member seed of today's European Union.","image":"/events/treaty-of-rome.webp","credit":"document: government of Italy scan: German Foreign (Office Auswärtiges Amt)","license":"Public domain"},"sputnik-1":{"name":"Sputnik opens the Space Age","country":"RU","kind":"science","year":1957,"description":"The Soviet Union lofted a beeping 58-centimetre metal sphere into orbit — the first artificial satellite. Its radio signal, audible to amateurs worldwide, started the space race.","image":"/events/sputnik-1.webp","credit":"Andrey Butko","license":"CC BY-SA 3.0"},"malayan-declaration-of-independence":{"name":"Malaya becomes independent","country":"MY","kind":"nation","year":1957,"description":"At midnight in Kuala Lumpur's Merdeka Stadium, the Federation of Malaya became independent of Britain to shouts of \"Merdeka!\" — freedom. Malaysia was formed six years later.","image":"/events/malayan-declaration-of-independence.webp","credit":"Orhanghazi","license":"CC BY-SA 4.0"},"cuban-revolution":{"name":"Cuban Revolution","country":"CU","kind":"revolution","year":1959,"description":"Fidel Castro's guerrillas came down from the Sierra Maestra and took Havana on New Year's Day as Batista fled. Within two years Cuba was a communist state ninety miles from Florida.","image":"/events/cuban-revolution.webp","license":"Public domain"},"independence-of-nigeria":{"name":"Nigeria becomes independent","country":"NG","kind":"nation","year":1960,"description":"Africa's most populous country took independence from Britain in 1960 — the \"Year of Africa\", when seventeen African nations raised new flags."},"independence-of-the-democratic-republic-of-the-congo":{"name":"The Congo becomes independent","country":"CD","kind":"nation","year":1960,"description":"Belgium handed over the Congo at two weeks' organised notice after decades of brutal rule. Within months the army mutinied, Katanga seceded and Prime Minister Lumumba was murdered.","image":"/events/independence-of-the-democratic-republic-of-the-congo.webp","credit":"PiotrMig","license":"CC BY-SA 4.0"},"vostok-1":{"name":"Gagarin — the first human in space","country":"RU","kind":"science","year":1961,"description":"Yuri Gagarin orbited the Earth once in 108 minutes aboard Vostok 1 and landed by parachute a national hero. He was 27, and the first human being to see the planet whole.","image":"/events/vostok-1.webp","credit":"Tempe","license":"Public domain"},"berlin-wall":{"name":"The Berlin Wall goes up","country":"DE","kind":"conflict","year":1961,"description":"East Germany sealed West Berlin overnight with barbed wire that hardened into a concrete wall, to stop the exodus of its own citizens — about one in six had already left. It stood for 28 years.","image":"/events/berlin-wall.webp","credit":"Edward Valachovic https://www.flickr.com/people/fauxaddress/","license":"CC BY-SA 2.0"},"evian-accords":{"name":"Algeria wins independence","country":"DZ","kind":"nation","year":1962,"description":"The accords signed at Évian ended an eight-year war that had killed hundreds of thousands and brought down France's Fourth Republic. A million French settlers left Algeria within months."},"cuban-missile-crisis":{"name":"Cuban Missile Crisis","country":"CU","kind":"conflict","year":1962,"description":"For thirteen October days the superpowers stood at the edge of nuclear war over Soviet missiles in Cuba, until Khrushchev withdrew them — and the US quietly pulled its own from Turkey.","image":"/events/cuban-missile-crisis.webp","credit":"Central Intelligence Agency","license":"Public domain"},"independence-of-jamaica":{"name":"Jamaica becomes independent","country":"JM","kind":"nation","year":1962,"description":"Jamaica left the failed West Indies Federation and took full independence from Britain, the first of the anglophone Caribbean islands to do so."},"organisation-of-african-unity":{"name":"Africa's states unite in one organisation","country":"ET","kind":"politics","year":1963,"description":"Thirty-two independent African states founded the OAU in Addis Ababa, pledging to finish decolonisation. It became the African Union in 2002, headquartered in the same city."},"assassination-of-john-f-kennedy":{"name":"Assassination of John F. Kennedy","country":"US","kind":"politics","year":1963,"description":"President Kennedy was shot dead in an open car in Dallas. The murder, caught on a bystander's home-movie camera, has fed six decades of grief and conspiracy alike.","image":"/events/assassination-of-john-f-kennedy.webp","credit":"Walt Cisco, Dallas Morning News","license":"Public domain"},"march-on-washington-for-jobs-and-freedom":{"name":"\"I Have a Dream\" — the March on Washington","country":"US","kind":"culture","year":1963,"description":"A quarter of a million people filled the Mall to demand civil rights, and Martin Luther King Jr. told them his dream from the Lincoln Memorial steps. The Civil Rights Act passed the next year.","image":"/events/march-on-washington-for-jobs-and-freedom.webp","credit":"Center for Jewish History, NYC","license":"Public domain"},"independence-of-singapore":{"name":"Singapore goes it alone","country":"SG","kind":"nation","year":1965,"description":"Expelled from Malaysia after two years, Singapore became a sovereign city-state against its own wishes — Lee Kuan Yew wept announcing it. It became one of the world's richest places anyway.","image":"/events/independence-of-singapore.webp","credit":"The Government of Malaysia and the Government of Singapore.","license":"Public domain"},"six-day-war":{"name":"Six-Day War","country":"IL","kind":"conflict","year":1967,"description":"Israel destroyed the Egyptian air force on the ground in the war's opening hours and in six days took Sinai, Gaza, the West Bank, East Jerusalem and the Golan — territories at the heart of the conflict since.","image":"/events/six-day-war.webp","credit":"Nicolas Eynaud","license":"CC BY-SA 3.0"},"first-heart-transplant":{"name":"The first human heart transplant","country":"ZA","kind":"science","year":1967,"description":"Christiaan Barnard's team at Cape Town's Groote Schuur Hospital transplanted a human heart for the first time. The patient lived 18 days; the operation changed what surgery believed possible."},"prague-spring":{"name":"Prague Spring","country":"CZ","kind":"revolution","year":1968,"description":"Czechoslovakia's reform communists promised \"socialism with a human face\" — until half a million Warsaw Pact troops arrived in August to shut it down. The thaw was over in a night.","image":"/events/prague-spring.webp","credit":"The Central Intelligence Agency","license":"Public domain"},"assassination-of-martin-luther-king-jr":{"name":"Assassination of Martin Luther King Jr.","country":"US","kind":"politics","year":1968,"description":"King was shot on a Memphis motel balcony at 39, in town to support striking sanitation workers. Riots broke out in over a hundred American cities in the week that followed.","image":"/events/assassination-of-martin-luther-king-jr.webp","credit":"Dick DeMarsico","license":"Public domain"},"apollo-11":{"name":"Apollo 11 — humans walk on the Moon","country":"US","kind":"science","year":1969,"description":"Armstrong and Aldrin landed on the Sea of Tranquility with about 25 seconds of fuel to spare while some 600 million people watched. Twelve people have walked the Moon; none since 1972.","image":"/events/apollo-11.webp","credit":"NASA","license":"Public domain"},"woodstock":{"name":"Woodstock","country":"US","kind":"culture","year":1969,"description":"Some 400,000 people descended on a dairy farm in upstate New York for three days of music and rain. The festival lost money, ran out of everything, and became the emblem of a generation.","image":"/events/woodstock.webp","credit":"Derek Redmond and Paul Campbell","license":"CC BY-SA 3.0"},"concorde":{"name":"Concorde's first flight","country":"FR","kind":"engineering","year":1969,"description":"The Anglo-French supersonic airliner flew for the first time from Toulouse. It crossed the Atlantic in under three and a half hours for 27 years — no passenger aircraft has gone supersonic since 2003.","image":"/events/concorde.webp","credit":"Eduard Marmet","license":"CC BY-SA 3.0"},"aswan-dam":{"name":"Work begins on the Aswan High Dam","country":"EG","kind":"engineering","year":1960,"description":"Begun in 1960 and completed a decade later, the Soviet-financed dam tamed the Nile's ancient flood and lit Egypt — while drowning Nubian homelands and forcing the block-by-block rescue of the Abu Simbel temples.","image":"/events/aswan-dam.webp","credit":"شرف الدين","license":"CC BY-SA 3.0"},"bangladesh-liberation-war":{"name":"Bangladesh is born","country":"BD","kind":"nation","year":1971,"description":"East Pakistan broke from the West in a nine-month war marked by genocide and ten million refugees. With India's intervention it ended in the birth of Bangladesh.","image":"/events/bangladesh-liberation-war.webp","credit":"Mike Young","license":"Public domain"},"1971-ugandan-coup-d-etat":{"name":"Idi Amin seizes Uganda","country":"UG","kind":"revolution","year":1971,"description":"General Idi Amin took Uganda while the president was abroad. His eight years killed perhaps 300,000 people and expelled the country's entire Asian community on ninety days' notice."},"munich-massacre":{"name":"Munich massacre","country":"DE","kind":"conflict","year":1972,"description":"Palestinian gunmen took the Israeli team hostage at the Munich Olympics; eleven athletes and coaches died, most in a botched rescue at the airport. The Games controversially went on.","image":"/events/munich-massacre.webp","credit":"AP Photo/Kurt Strumpf (? – 2014)","license":"Public domain"},"sydney-opera-house":{"name":"The Sydney Opera House opens","country":"AU","kind":"engineering","year":1973,"description":"Jørn Utzon's sail-roofed masterpiece opened ten years late and fourteen times over budget — its Danish architect had resigned and never returned to see it finished.","image":"/events/sydney-opera-house.webp","license":"CC BY-SA 3.0"},"1973-chilean-coup-d-etat":{"name":"Pinochet's coup in Chile","country":"CL","kind":"revolution","year":1973,"description":"The armed forces bombed the presidential palace, President Allende died there, and General Pinochet's junta ruled for 17 years — thousands were executed, tortured or disappeared.","image":"/events/1973-chilean-coup-d-etat.webp","credit":"Biblioteca del Congreso Nacional de Chile","license":"CC BY 3.0 cl"},"1973-oil-crisis":{"name":"1973 oil crisis","country":"SA","kind":"politics","year":1973,"description":"Arab oil producers embargoed the West over the October war with Israel and prices quadrupled in months — queues at petrol pumps, speed limits, and the end of the postwar boom.","image":"/events/1973-oil-crisis.webp","credit":"Warren K. Leffler, U.S. News &amp; World Report Magazine","license":"Public domain"},"carnation-revolution":{"name":"Carnation Revolution","country":"PT","kind":"revolution","year":1974,"description":"Junior officers toppled Europe's oldest dictatorship in a day, signalled by songs on the radio, and crowds put carnations in the soldiers' rifle barrels. Portugal's African colonies were free within two years."},"turkish-invasion-of-cyprus":{"name":"Cyprus is divided","country":"CY","kind":"conflict","year":1974,"description":"After a Greek-backed coup aimed at union with Greece, Turkey invaded and took the island's north. A UN buffer zone has split Cyprus — and its capital Nicosia — ever since.","image":"/events/turkish-invasion-of-cyprus.webp","credit":"Alexander-Michael Hadjilyra","license":"CC BY 3.0"},"fall-of-saigon":{"name":"The Vietnam War ends","country":"VN","kind":"conflict","year":1975,"description":"North Vietnamese tanks broke through the gates of Saigon's Presidential Palace as the last Americans left by helicopter from an embassy roof. Vietnam was reunified after thirty years of war.","image":"/events/fall-of-saigon.webp","credit":"User:Ctmt","license":"Public domain"},"independence-of-angola":{"name":"Angola becomes independent","country":"AO","kind":"nation","year":1975,"description":"Angola took independence as Portugal's empire collapsed after the Carnation Revolution — and slid straight into a superpower-fuelled civil war that ran, with pauses, until 2002."},"death-of-francisco-franco":{"name":"Franco dies — Spain turns to democracy","country":"ES","kind":"politics","year":1975,"description":"Franco died after 36 years of dictatorship, and the king he had groomed, Juan Carlos, steered Spain instead to parliamentary democracy within three years."},"soweto-uprising":{"name":"Soweto uprising","country":"ZA","kind":"revolution","year":1976,"description":"Soweto's schoolchildren marched against being taught in Afrikaans and the police opened fire. Hundreds died in the months that followed, and a generation was radicalised against apartheid.","image":"/events/soweto-uprising.webp","credit":"Sam Nzima","license":"Public domain"},"1976-tangshan-earthquake":{"name":"1976 Tangshan earthquake","country":"CN","kind":"disaster","year":1976,"description":"An earthquake flattened the industrial city of Tangshan before dawn, killing at least 240,000 people by official count — the deadliest earthquake of the twentieth century.","image":"/events/1976-tangshan-earthquake.webp","credit":"the National Oceanic and Atmospheric Administration","license":"Public domain"},"voyager-1":{"name":"Voyager 1 leaves for the outer planets","country":"US","kind":"science","year":1977,"description":"Launched to fly past Jupiter and Saturn, Voyager 1 kept going — now the most distant human-made object, carrying a golden record of Earth's sounds, and still calling home from interstellar space.","image":"/events/voyager-1.webp","credit":"NASA/JPL","license":"Public domain"},"camp-david-accords":{"name":"Camp David Accords","country":"EG","kind":"politics","year":1978,"description":"Thirteen secret days at the US presidential retreat produced a framework for peace between Egypt and Israel — the first Arab state to recognise Israel. Sadat paid for it with his life three years later.","image":"/events/camp-david-accords.webp","credit":"Fitz-Patrick, Bill, photographer","license":"Public domain"},"iranian-revolution":{"name":"Iranian Revolution","country":"IR","kind":"revolution","year":1979,"description":"Mass protests drove out the Shah, and Ayatollah Khomeini returned from exile to found an Islamic republic. The US embassy hostage crisis began within the year.","image":"/events/iranian-revolution.webp","credit":"Unknown authorUnknown author","license":"GFDL"},"soviet-afghan-war":{"name":"The Soviets invade Afghanistan","country":"AF","kind":"conflict","year":1979,"description":"Soviet troops took Kabul in the last week of 1979 and stayed nine years, fighting US-armed mujahideen. The war helped exhaust the USSR — and seeded the conflicts that followed.","image":"/events/soviet-afghan-war.webp","credit":"LLs","license":"CC BY-SA 4.0"},"independence-of-zimbabwe":{"name":"Zimbabwe becomes independent","country":"ZW","kind":"nation","year":1980,"description":"White-ruled Rhodesia became independent Zimbabwe after a long guerrilla war and the Lancaster House settlement. Robert Mugabe won the first elections — and held power for 37 years."},"solidarity-polish-trade-union":{"name":"Solidarity is born in the Gdańsk shipyard","country":"PL","kind":"revolution","year":1980,"description":"Striking Gdańsk shipyard workers led by Lech Wałęsa forced the communist state to accept the Soviet bloc's first independent trade union. Ten million Poles joined within a year.","image":"/events/solidarity-polish-trade-union.webp","credit":"Zenon Mirota","license":"CC BY-SA 3.0 pl"},"iran-iraq-war":{"name":"Iran–Iraq War","country":"IQ","kind":"conflict","year":1980,"description":"Saddam Hussein invaded revolutionary Iran expecting a quick win and got eight years of trench warfare, poison gas and perhaps half a million dead — borders ending where they began.","image":"/events/iran-iraq-war.webp","credit":"Mahmoud Badrfar","license":"GFDL"},"falklands-war":{"name":"Falklands War","country":"AR","kind":"conflict","year":1982,"description":"Argentina's junta seized the Falkland Islands and Britain took them back in a ten-week war fought 13,000 kilometres from home. Defeat brought down the junta within a year.","image":"/events/falklands-war.webp","credit":"Department of History, United States Military Academy","license":"Public domain"},"bhopal-disaster":{"name":"Bhopal disaster","country":"IN","kind":"disaster","year":1984,"description":"A Union Carbide pesticide plant leaked toxic gas over sleeping Bhopal, killing thousands within days and injuring hundreds of thousands — the world's deadliest industrial disaster.","image":"/events/bhopal-disaster.webp","credit":"Bhopal Medical Appeal, Martin Stott","license":"CC BY-SA 2.0"},"live-aid":{"name":"Live Aid","country":"GB","kind":"culture","year":1985,"description":"Twin concerts at Wembley and Philadelphia — sixteen hours, broadcast to well over a billion people — raised over £100 million for Ethiopia's famine. Queen's twenty minutes became rock legend.","image":"/events/live-aid.webp","credit":"Squelle","license":"CC BY-SA 3.0"},"1985-mexico-city-earthquake":{"name":"1985 Mexico City earthquake","country":"MX","kind":"disaster","year":1985,"description":"A magnitude-8 earthquake collapsed hundreds of buildings in Mexico City, killing at least ten thousand people. Citizen rescue brigades, organised where the state failed, reshaped Mexican civil society.","image":"/events/1985-mexico-city-earthquake.webp","credit":"United States Geological Survey","license":"Public domain"},"chernobyl-disaster":{"name":"Chernobyl disaster","country":"UA","kind":"disaster","year":1986,"description":"Reactor 4 exploded during a botched safety test, spreading fallout across Europe while Moscow stayed silent for days. Gorbachev later called it a true cause of the Soviet collapse.","image":"/events/chernobyl-disaster.webp","credit":"IAEA Imagebank","license":"CC BY-SA 2.0"},"space-shuttle-challenger-disaster":{"name":"Space Shuttle Challenger disaster","country":"US","kind":"disaster","year":1986,"description":"Challenger broke apart 73 seconds after liftoff, killing all seven aboard — including the teacher Christa McAuliffe, with schoolchildren across America watching live. A frozen rubber O-ring was to blame.","image":"/events/space-shuttle-challenger-disaster.webp","credit":"Kennedy Space Center","license":"Public domain"},"people-power-revolution":{"name":"People Power Revolution","country":"PH","kind":"revolution","year":1986,"description":"Millions of Filipinos filled Manila's EDSA highway, nuns kneeling in front of tanks, until Ferdinand Marcos fled after a stolen election. Corazon Aquino — a slain rival's widow — became president.","image":"/events/people-power-revolution.webp","credit":"Alternativity","license":"CC BY-SA 4.0"},"world-wide-web":{"name":"The World Wide Web is invented","country":"CH","kind":"science","year":1989,"description":"At CERN, Tim Berners-Lee proposed a hypertext system for sharing physics papers; his manager pencilled \"vague, but exciting\". He gave the Web away patent-free.","image":"/events/world-wide-web.webp","credit":"Raimundo Pastor","license":"CC BY-SA 4.0"},"baltic-way":{"name":"Two million join hands across the Baltics","country":"LT","kind":"revolution","year":1989,"description":"Some two million Estonians, Latvians and Lithuanians joined hands in an unbroken 675-kilometre chain to demand independence, fifty years to the day after the pact that had handed them to Stalin.","image":"/events/baltic-way.webp","credit":"Kusurija","license":"CC BY-SA 3.0"},"1989-tiananmen-square-protests-and-massacre":{"name":"Tiananmen Square","country":"CN","kind":"revolution","year":1989,"description":"Weeks of student-led protests for reform filled Tiananmen Square until the army cleared Beijing with tanks and live fire, killing hundreds at least. The lone \"Tank Man\" photo endures where the count is censored."},"fall-of-the-berlin-wall":{"name":"Fall of the Berlin Wall","country":"DE","kind":"revolution","year":1989,"description":"A fumbled press conference answer — travel is free, \"immediately, without delay\" — sent East Berliners to the checkpoints that night, and the guards stood aside. The Cold War's symbol fell to hands and hammers.","image":"/events/fall-of-the-berlin-wall.webp","credit":"Sue Ream, photographer (San Francisco, California)","license":"CC BY 3.0"},"velvet-revolution":{"name":"Velvet Revolution","country":"CZ","kind":"revolution","year":1989,"description":"Ten days of swelling, entirely peaceful protests ended communist rule in Czechoslovakia. By the year's end the dissident playwright Václav Havel — in prison that spring — was president.","image":"/events/velvet-revolution.webp","credit":"RobbieIanMorrison","license":"CC BY 4.0"},"romanian-revolution":{"name":"Romanian Revolution","country":"RO","kind":"revolution","year":1989,"description":"The only violent fall in Eastern Europe's year of revolutions: a week of fighting ended with the Ceaușescus tried by a drumhead court and shot on Christmas Day.","image":"/events/romanian-revolution.webp","credit":"Not credited","license":"Attribution"},"1995-rugby-world-cup":{"name":"The Rainbow Nation wins the Rugby World Cup","country":"ZA","kind":"culture","year":1995,"description":"A year into democracy, South Africa hosted the tournament and won it — and Nelson Mandela handed François Pienaar the trophy wearing the Springboks' jersey, apartheid's old symbol turned unifier.","image":"/events/1995-rugby-world-cup.webp","credit":"Blackcat","license":"CC BY-SA 4.0"},"german-reunification":{"name":"German reunification","country":"DE","kind":"nation","year":1990,"description":"Less than a year after the Wall fell, East Germany's five states acceded to the Federal Republic and Germany was one country again — 3 October is now its national day.","image":"/events/german-reunification.webp","credit":"Peer Grimm","license":"CC BY-SA 3.0 de"},"independence-of-namibia":{"name":"Namibia becomes independent","country":"NA","kind":"nation","year":1990,"description":"Africa's last colony became independent from South African rule after a decades-long liberation war and a UN-supervised transition — one of the closing acts of both empire and Cold War."},"hubble-space-telescope":{"name":"Hubble is launched","country":"US","kind":"science","year":1990,"description":"The first great space telescope launched with a flawed mirror — corrected by spacewalking astronauts three years later. Its deep-field images showed thousands of galaxies in a patch of \"empty\" sky.","image":"/events/hubble-space-telescope.webp","credit":"NASA","license":"Public domain"},"gulf-war":{"name":"Iraq invades Kuwait — the Gulf War","country":"KW","kind":"conflict","year":1990,"description":"Saddam Hussein swallowed Kuwait in a day; a 35-nation coalition threw him out in a six-week air war and a hundred-hour ground campaign, watched live on satellite news.","image":"/events/gulf-war.webp","credit":"US Air Force","license":"Public domain"},"croatian-war-of-independence":{"name":"Yugoslavia begins to break apart","country":"HR","kind":"conflict","year":1991,"description":"Croatia's declaration of independence brought war with the Yugoslav army and Serb militias — the siege of Vukovar, the shelling of Dubrovnik — as the federation tore apart piece by piece.","image":"/events/croatian-war-of-independence.webp","license":"CC BY-SA 3.0"},"dissolution-of-the-soviet-union":{"name":"Dissolution of the Soviet Union","country":"RU","kind":"nation","year":1991,"description":"After a failed hardline coup, the republics walked away and Gorbachev resigned on Christmas Day as the red flag came down from the Kremlin. Fifteen states stood where the superpower had been.","image":"/events/dissolution-of-the-soviet-union.webp","credit":"Yuriy Kuydin / Юрий Куйдин","license":"CC BY-SA 3.0"},"maastricht-treaty":{"name":"The European Union is created","country":"NL","kind":"politics","year":1992,"description":"Signed in the Dutch city of Maastricht, the treaty turned the Community into the European Union, created EU citizenship and set the path to a single currency.","image":"/events/maastricht-treaty.webp","credit":"User:Mateus2019","license":"CC BY 2.0 de"},"dissolution-of-czechoslovakia":{"name":"The Velvet Divorce","country":"SK","kind":"nation","year":1993,"description":"Czechoslovakia split into the Czech Republic and Slovakia at midnight on New Year's Eve — negotiated by two prime ministers, without a referendum and without a shot.","image":"/events/dissolution-of-czechoslovakia.webp","credit":"PANONIAN","license":"Public domain"},"oslo-i-accord":{"name":"The Oslo Accords","country":"IL","kind":"politics","year":1993,"description":"Negotiated secretly in Norway and sealed with a Rabin–Arafat handshake on the White House lawn, the accords brought mutual recognition and Palestinian self-rule in parts of the territories — but no final peace.","image":"/events/oslo-i-accord.webp","credit":"Vince Musi / The White House","license":"Public domain"},"independence-of-eritrea":{"name":"Eritrea becomes independent","country":"ER","kind":"nation","year":1993,"description":"After a thirty-year war against Ethiopia — Africa's longest independence struggle — Eritreans voted almost unanimously for statehood in a UN-supervised referendum."},"rwandan-genocide":{"name":"Rwandan genocide","country":"RW","kind":"conflict","year":1994,"description":"In roughly one hundred days, Hutu extremists murdered around 800,000 Tutsi and moderate Hutu — much of it by machete, neighbour against neighbour — while the world declined to intervene.","image":"/events/rwandan-genocide.webp","credit":"Fanny Schertzer","license":"CC BY-SA 3.0"},"1994-south-african-general-election":{"name":"Apartheid ends at the ballot box","country":"ZA","kind":"nation","year":1994,"description":"South Africans of all races voted together for the first time, queueing for hours in lines visible from the air. Nelson Mandela was inaugurated president two weeks later."},"channel-tunnel":{"name":"The Channel Tunnel opens","country":"GB","kind":"engineering","year":1994,"description":"Two centuries after the idea was first floated, a 50-kilometre rail tunnel — 38 of them under the seabed — joined Britain to the European mainland for the first time since the Ice Age.","image":"/events/channel-tunnel.webp","credit":"Billy69150 (voir les conditions d'utilisation / see licensing below)","license":"CC BY-SA 4.0"},"dayton-agreement":{"name":"The Bosnian War ends at Dayton","country":"BA","kind":"politics","year":1995,"description":"Three years of siege and ethnic cleansing — including genocide at Srebrenica that summer — ended with a peace hammered out at a US airbase in Ohio, freezing Bosnia into two entities under one roof.","image":"/events/dayton-agreement.webp","credit":"U.S. Air Force/Staff Sgt. Brian Schlumbohm","license":"Public domain"},"dolly-the-sheep":{"name":"Dolly the sheep is cloned","country":"GB","kind":"science","year":1996,"description":"Scientists near Edinburgh cloned a sheep from a single adult udder cell — the first cloned mammal, named after Dolly Parton for exactly the reason you suspect.","image":"/events/dolly-the-sheep.webp","credit":"Toni Barros from São Paulo, Brasil","license":"CC BY-SA 2.0"},"handover-of-hong-kong":{"name":"Handover of Hong Kong","country":"HK","kind":"politics","year":1997,"description":"Britain returned Hong Kong to China at midnight in a rain-soaked ceremony, ending 156 years of colonial rule under a promise of \"one country, two systems\" for fifty years.","image":"/events/handover-of-hong-kong.webp","credit":"Dan Lundberg","license":"CC BY-SA 2.0"},"1997-asian-financial-crisis":{"name":"1997 Asian financial crisis","country":"TH","kind":"disaster","year":1997,"description":"Thailand's forced float of the baht set off a contagion that crashed currencies and economies from Jakarta to Seoul, humbling the \"Asian tigers\" and toppling Indonesia's Suharto.","image":"/events/1997-asian-financial-crisis.webp","credit":"Max Roser","license":"CC BY 4.0"},"good-friday-agreement":{"name":"Good Friday Agreement","country":"GB","kind":"politics","year":1998,"description":"Signed in Belfast on Good Friday, the agreement largely ended thirty years of the Troubles — power-sharing, paramilitary disarmament, and an open border on the island of Ireland."},"international-space-station":{"name":"The International Space Station begins","country":"US","kind":"science","year":1998,"description":"A Russian module launched from Baikonur and an American one joined it weeks later, beginning the largest structure ever assembled in space. It has been continuously inhabited since 2000.","image":"/events/international-space-station.webp","credit":"NASA","license":"Public domain"},"euro":{"name":"The euro is born","country":"DE","kind":"politics","year":1999,"description":"Eleven EU countries locked their currencies into the euro; notes and coins followed in 2002, retiring the franc, mark, lira and peseta. It is now money for over 340 million people.","image":"/events/euro.webp","credit":"The RedBurn","license":"ECB decisions ECB/2003/4 and ECB/2003/5"},"torrijos-carter-treaties":{"name":"America promises the canal to Panama","country":"PA","kind":"politics","year":1977,"description":"Carter and Panama's Torrijos signed the treaties returning the canal — the handover itself came at noon on the last day of 1999, ending nearly a century of American control.","image":"/events/torrijos-carter-treaties.webp","credit":"White House photo","license":"Public domain"},"september-11-attacks":{"name":"September 11 attacks","country":"US","kind":"conflict","year":2001,"description":"Al-Qaeda hijackers flew airliners into the World Trade Center and the Pentagon, killing nearly 3,000 people. The wars that answered it ran for two decades.","image":"/events/september-11-attacks.webp","credit":"Robert on Flickr","license":"CC BY-SA 2.0"},"wikipedia":{"name":"Wikipedia launches","country":"US","kind":"culture","year":2001,"description":"An encyclopedia anyone could edit sounded like a joke and became one of the most visited sites on Earth — millions of articles in hundreds of languages, written free by volunteers.","image":"/events/wikipedia.webp","credit":"最終編集","license":"CC BY-SA 4.0"},"east-timor":{"name":"East Timor becomes independent","country":"TL","kind":"nation","year":2002,"description":"The first new state of the century rose from a quarter-century of brutal Indonesian occupation and a UN-run transition after its people voted overwhelmingly for freedom in 1999.","image":"/events/east-timor.webp","credit":"See File history below for details. Denelson83, Zscout370 ve Madden","license":"Public domain"},"iraq-war":{"name":"Iraq War","country":"IQ","kind":"conflict","year":2003,"description":"A US-led coalition invaded to seize weapons of mass destruction that were never found. Saddam fell in three weeks; the insurgency and civil war that followed lasted years.","image":"/events/iraq-war.webp","credit":"Technical Sergeant John L. Houghton, Jr., United States Air Force","license":"Public domain"},"human-genome-project":{"name":"The human genome is sequenced","country":"US","kind":"science","year":2003,"description":"The thirteen-year international project to read all three billion letters of human DNA was declared complete — the book of the species, open source.","image":"/events/human-genome-project.webp","credit":"U.S. Department of Energy, Human Genome Project","license":"Public domain"},"2004-indian-ocean-earthquake-and-tsunami":{"name":"2004 Indian Ocean earthquake and tsunami","country":"ID","kind":"disaster","year":2004,"description":"A magnitude-9 earthquake off Sumatra sent tsunamis across the whole ocean, killing some 230,000 people in fourteen countries on a single morning — many with no warning at all.","image":"/events/2004-indian-ocean-earthquake-and-tsunami.webp","credit":"David Rydevik (email: david.rydevikgmail.com), Stockholm, Sweden.","license":"Public domain"},"2004-enlargement-of-the-european-union":{"name":"The EU takes in ten new members","country":"PL","kind":"politics","year":2004,"description":"Ten countries — eight of them from behind the old Iron Curtain — joined the EU in its largest single expansion, stitching the continent's Cold War halves together.","image":"/events/2004-enlargement-of-the-european-union.webp","credit":"JLogan","license":"CC BY-SA 3.0"},"orange-revolution":{"name":"Orange Revolution","country":"UA","kind":"revolution","year":2004,"description":"A rigged presidential run-off brought hundreds of thousands into a frozen Kyiv's Independence Square for weeks, until the courts ordered a re-vote — which the opposition won.","image":"/events/orange-revolution.webp","credit":"Serhiy","license":"CC BY-SA 3.0"},"hurricane-katrina":{"name":"Hurricane Katrina","country":"US","kind":"disaster","year":2005,"description":"Katrina's surge broke New Orleans' levees and drowned four-fifths of the city. Some 1,400 died, and the images of Americans stranded on rooftops indicted every level of government.","image":"/events/hurricane-katrina.webp","credit":"NASA","license":"Public domain"},"2006-montenegrin-independence-referendum":{"name":"Montenegro votes for independence","country":"ME","kind":"nation","year":2006,"description":"Montenegro voted to leave its union with Serbia — clearing the 55% bar by half a point — and the last piece of the old Yugoslavia went its own way.","image":"/events/2006-montenegrin-independence-referendum.webp","credit":"Furfur","license":"CC BY-SA 4.0"},"iphone-1st-generation":{"name":"The iPhone arrives","country":"US","kind":"culture","year":2007,"description":"Steve Jobs introduced \"an iPod, a phone and an internet communicator\" — one device. The smartphone it defined put the internet in most of humanity's pockets within a decade."},"2008-kosovo-declaration-of-independence":{"name":"Kosovo declares independence","country":"XK","kind":"nation","year":2008,"description":"Nine years after the NATO intervention, Kosovo's assembly declared independence from Serbia. About half the world's states recognise it; Serbia and Russia do not.","image":"/events/2008-kosovo-declaration-of-independence.webp","credit":"Ensar.koshi","license":"CC BY-SA 3.0"},"bankruptcy-of-lehman-brothers":{"name":"Lehman falls — the global financial crisis","country":"US","kind":"disaster","year":2008,"description":"The 158-year-old investment bank filed the largest bankruptcy in US history and the global financial system seized. The Great Recession that followed cost millions their homes and jobs.","image":"/events/bankruptcy-of-lehman-brothers.webp","credit":"David Shankbone","license":"CC BY-SA 3.0"},"russo-georgian-war":{"name":"Russo-Georgian War","country":"GE","kind":"conflict","year":2008,"description":"A five-day August war over South Ossetia ended with Russian troops deep in Georgia and two breakaway regions under de facto Russian control — Europe's first invasion of the century.","image":"/events/russo-georgian-war.webp","credit":"Yana Amelina (Амелина Я. А.)","license":"CC BY-SA 3.0"},"first-inauguration-of-barack-obama":{"name":"America inaugurates its first Black president","country":"US","kind":"politics","year":2009,"description":"Barack Obama took the oath before a record crowd on the National Mall, 45 years after the March on Washington filled the same ground.","image":"/events/first-inauguration-of-barack-obama.webp","credit":"Master Sgt. Cecilio Ricardo, U.S. Air Force","license":"Public domain"},"2010-haiti-earthquake":{"name":"2010 Haiti earthquake","country":"HT","kind":"disaster","year":2010,"description":"A magnitude-7 earthquake struck just outside Port-au-Prince, killing well over 100,000 people and flattening much of the capital of the hemisphere's poorest country.","image":"/events/2010-haiti-earthquake.webp","credit":"Trocaire from Ireland","license":"CC BY 2.0"},"burj-khalifa":{"name":"The Burj Khalifa opens","country":"AE","kind":"engineering","year":2010,"description":"Dubai opened the tallest structure humans have ever built — 828 metres, nearly twice the old record holder Taipei 101 — renamed at the last minute for the Abu Dhabi ruler whose bailout saved it.","image":"/events/burj-khalifa.webp","credit":"Tim.Reckmann","license":"CC BY-SA 3.0"},"tunisian-revolution":{"name":"The Arab Spring begins in Tunisia","country":"TN","kind":"revolution","year":2010,"description":"A street vendor's self-immolation in a provincial town lit protests that drove out Tunisia's president in 28 days — and spread revolt across the Arab world within weeks.","image":"/events/tunisian-revolution.webp","credit":"M.Rais","license":"CC0"},"2011-tohoku-earthquake-and-tsunami":{"name":"The tsunami and Fukushima","country":"JP","kind":"disaster","year":2011,"description":"Japan's strongest recorded earthquake sent a tsunami over the sea walls, killing nearly 20,000 people and triggering meltdowns at the Fukushima Daiichi nuclear plant — the worst since Chernobyl.","image":"/events/2011-tohoku-earthquake-and-tsunami.webp","credit":"U.S. Navy photo","license":"Public domain"},"independence-of-south-sudan":{"name":"South Sudan — the world's newest country","country":"SS","kind":"nation","year":2011,"description":"After decades of civil war and a near-unanimous referendum, South Sudan became the world's newest country. Civil war within it followed two years later."},"syrian-civil-war":{"name":"Syrian civil war","country":"SY","kind":"conflict","year":2011,"description":"The Arab Spring's Syrian protests met bullets and spiralled into a war that has killed hundreds of thousands and displaced half the country — the largest refugee crisis of the era.","image":"/events/syrian-civil-war.webp","credit":"Ermanarich","license":"CC BY-SA 4.0"},"higgs-boson":{"name":"The Higgs boson is found","country":"CH","kind":"science","year":2012,"description":"CERN's Large Hadron Collider found the particle predicted 48 years earlier to explain why matter has mass. Peter Higgs, in the audience, wiped away tears; the Nobel came the next year.","image":"/events/higgs-boson.webp","credit":"Lucas Taylor / CERN","license":"CC BY-SA 3.0"},"2013-papal-conclave":{"name":"The first pope from the Americas","country":"VA","kind":"culture","year":2013,"description":"After the first papal resignation in six centuries, the conclave chose Buenos Aires's Jorge Bergoglio — the first pope from the Americas, the southern hemisphere, or the Jesuits. He took the name Francis.","image":"/events/2013-papal-conclave.webp","credit":"Casa Rosada","license":"CC BY-SA 2.0"},"annexation-of-crimea-by-the-russian-federation":{"name":"Russia annexes Crimea","country":"UA","kind":"conflict","year":2014,"description":"Unmarked Russian troops — the \"little green men\" — seized Crimea weeks after Ukraine's revolution, and Moscow annexed it after a referendum recognised almost nowhere. Europe's borders had been redrawn by force.","image":"/events/annexation-of-crimea-by-the-russian-federation.webp","credit":"Elizabeth Arrott","license":"Public domain"},"western-african-ebola-virus-epidemic":{"name":"The West African Ebola epidemic","country":"GN","kind":"disaster","year":2014,"description":"From a single village in Guinea, Ebola spread through Liberia and Sierra Leone in the worst outbreak of the disease ever — over 11,000 dead before it was contained.","image":"/events/western-african-ebola-virus-epidemic.webp","credit":"ZeLonewolf","license":"CC0"},"paris-agreement":{"name":"Paris Agreement","country":"FR","kind":"politics","year":2015,"description":"Nearly every nation on Earth agreed in Paris to keep global warming well below 2°C. Delegates wept and cheered when the gavel fell — the treaty's test has been every year since.","image":"/events/paris-agreement.webp","credit":"L.tak","license":"CC BY-SA 4.0"},"2016-united-kingdom-european-union-membership-referendum":{"name":"Brexit — Britain votes to leave","country":"GB","kind":"politics","year":2016,"description":"Britain voted 52–48 to leave the European Union, the first member ever to go. The prime minister resigned the next morning; the leaving took four and a half more years.","image":"/events/2016-united-kingdom-european-union-membership-referendum.webp","credit":"The Electoral Commission","license":"Public domain"},"colombian-peace-agreement":{"name":"Colombia signs peace with the FARC","country":"CO","kind":"politics","year":2016,"description":"The government and the FARC guerrillas signed an end to the western hemisphere's longest war — half a century, 260,000 dead. Voters rejected the first draft; a revised deal passed weeks later.","image":"/events/colombian-peace-agreement.webp","credit":"Milenioscuro","license":"CC BY-SA 4.0"},"notre-dame-fire":{"name":"Notre-Dame burns","country":"FR","kind":"disaster","year":2019,"description":"Fire took the roof and spire of the 850-year-old cathedral as Paris watched from the bridges, singing hymns. The towers and the rose windows survived; it reopened in 2024.","image":"/events/notre-dame-fire.webp","credit":"LeLaisserPasserA38","license":"CC BY-SA 4.0"},"covid-19-pandemic":{"name":"COVID-19 pandemic","country":"CN","kind":"disaster","year":2020,"description":"A novel coronavirus first reported in Wuhan closed borders, schools and cities across the planet within months — millions dead, and vaccines developed at record speed inside a year.","image":"/events/covid-19-pandemic.webp","credit":"Gustavo Basso","license":"CC BY-SA 4.0"},"2020-beirut-explosion":{"name":"The Beirut port explosion","country":"LB","kind":"disaster","year":2020,"description":"Some 2,750 tonnes of ammonium nitrate, stored for six years in a port warehouse, detonated in one of the largest non-nuclear blasts ever recorded — over 200 dead and 300,000 homeless in seconds.","image":"/events/2020-beirut-explosion.webp","credit":"Mahdi Shojaeian","license":"CC BY 4.0"},"fall-of-kabul":{"name":"The Taliban retake Kabul","country":"AF","kind":"conflict","year":2021,"description":"As the twenty-year Western mission ended, the Afghan government collapsed in days and the Taliban entered Kabul without a fight. The desperate airlift from the airport closed America's longest war.","image":"/events/fall-of-kabul.webp","credit":"VOA","license":"Public domain"},"james-webb-space-telescope":{"name":"The James Webb Space Telescope launches","country":"US","kind":"science","year":2021,"description":"The long-delayed successor to Hubble launched on Christmas Day and unfolded itself perfectly a million miles out. Its infrared eyes see the first galaxies forming.","image":"/events/james-webb-space-telescope.webp","credit":"NASA","license":"Public domain"},"russian-invasion-of-ukraine":{"name":"Russian invasion of Ukraine","country":"UA","kind":"conflict","year":2022,"description":"Russia launched a full-scale invasion of Ukraine from the north, east and south, expecting Kyiv to fall in days. It did not — and Europe's largest war since 1945 began.","image":"/events/russian-invasion-of-ukraine.webp","credit":"Arrikel","license":"CC BY-SA 4.0"},"death-and-state-funeral-of-elizabeth-ii":{"name":"Elizabeth II dies","country":"GB","kind":"culture","year":2022,"description":"Britain's longest-reigning monarch died at Balmoral after seventy years on the throne. The queue to pass her coffin in Westminster Hall ran for kilometres along the Thames, day and night.","image":"/events/death-and-state-funeral-of-elizabeth-ii.webp","credit":"Taras Young","license":"Public domain"},"2022-fifa-world-cup":{"name":"The Qatar World Cup final","country":"QA","kind":"culture","year":2022,"description":"The first World Cup in the Arab world, played in winter, ended with what many call the greatest final ever — Messi's Argentina beating Mbappé's France on penalties after 3–3."},"2023-turkey-syria-earthquakes":{"name":"2023 Turkey–Syria earthquakes","country":"TR","kind":"disaster","year":2023,"description":"Two huge earthquakes hours apart flattened cities across southern Türkiye and northern Syria in the winter cold, killing nearly 60,000 people — Türkiye's worst disaster of the modern era.","image":"/events/2023-turkey-syria-earthquakes.webp","credit":"Adem","license":"CC BY-SA 4.0"},"1990-mongolian-revolution":{"name":"Mongolia turns democratic","country":"MN","kind":"revolution","year":1990,"description":"Hunger strikes and mass protests in freezing Ulaanbaatar persuaded the communist politburo to resign en masse — a peaceful exit, and Asia's first post-Soviet democracy.","image":"/events/1990-mongolian-revolution.webp","credit":"Jam123","license":"CC0"},"kyoto-protocol":{"name":"Kyoto Protocol","country":"JP","kind":"politics","year":1997,"description":"The first treaty binding industrialised countries to cut greenhouse-gas emissions was adopted in Kyoto — the ancestor, through years of argument, of the Paris Agreement.","image":"/events/kyoto-protocol.webp","credit":"L.tak","license":"CC BY-SA 3.0"}}
